head.script:
//
(function() {
  try {
    var t = localStorage.getItem('app-theme-preference');
    if (!t) {
      t = (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) ? 'dark' : 'light';
    }
    document.documentElement.setAttribute('data-theme', t);
    var p = localStorage.getItem('app-palette-preference') || 'default';
    document.documentElement.setAttribute('data-palette', p);
  } catch(e) {}
})();
//

head.b:skin:
/* ==========================================================================
   GLOBAL CSS - Base Styles, Plus Jakarta Sans & Geist Mono Fonts, Tokens, Material Subtle Palettes & Focus Rings
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Geist+Mono:wght@300;400;500;600;700;800&display=swap');
@import '../assets/css/icons.css';
@import './share-modal.css';

/* Plus Jakarta Sans font is loaded with preconnect in index.html to eliminate CLS */

/* Suppress all transitions and animations during initial page load to prevent lag and paint flash */
.preload,
.preload *,
.preload *::before,
.preload *::after {
  transition: none !important;
  animation: none !important;
}

/* --------------------------------------------------------------------------
   Default CSS Variables (Default: Beige Subtle Palette)
   -------------------------------------------------------------------------- */
:root {
  /* Typography with robust system fallback metrics to eliminate CLS */
  --font-family-base: 'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-family-mono: 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace;
  --font-size-base: 16px;
  --line-height-base: 1.55;

  /* Centralized Typography Scale Tokens */
  --text-2xs: 11.5px;
  --text-xs: 12.5px;
  --text-sm: 13.5px;
  --text-md: 14.5px;
  --text-base: 15.5px;
  --text-lg: 17px;
  --text-xl: 19px;
  --text-2xl: 22px;
  --text-3xl: 26px;
  --text-hero: clamp(22px, 2.8vw, 30px);

  /* Font Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xl: 32px;

  /* Transitions */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-normal: 240ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 320ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Specific Radii */
  --radius-btn-subtle: 5px; /* 5px subtle pill effect */
  --radius-modal: 12px;     /* 12px for modals */
  --radius-input: 12px;     /* 12px for input field */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;

  /* Header Height */
  --header-height: 60px;
  --header-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);

  /* Fluid edge-to-edge layout with uniform margin and component gap */
  --page-gutter: 12px;
  --page-max-width: 100%;

  /* Swatch Dot Colors for UI Selector */
  --dot-default: #18181b;
  --dot-beige: #8d7053;
  --dot-green: #3d805c;
  --dot-orange: #c4682c;
  --dot-blue: #3b76bb;
  --dot-teal: #2c857f;
  --dot-brown: #846045;
  --dot-pink: #b84a7a;
  --dot-purple: #754ba1;
  --dot-magenta: #a33880;
  --dot-red: #ba4040;

  /* SVG & Icon Fill token */
  --fillg: currentColor;

  /* Text Colors (Neutral) */
  --color-text-primary: #191816;
  --color-text-secondary: #57534e;
  --color-text-tertiary: #958f88;
  --btn-icon-color: #44403c;
  --btn-icon-hover-color: #1c1917;

  /* Dynamic Header Action Buttons subtle theme backgrounds */
  --header-btn-bg: color-mix(in srgb, var(--accent-color) 14%, transparent);
  --header-btn-border: color-mix(in srgb, var(--accent-color) 22%, transparent);
  --header-btn-hover-bg: color-mix(in srgb, var(--accent-color) 22%, transparent);
  --header-btn-hover-border: color-mix(in srgb, var(--accent-color) 32%, transparent);
  --header-btn-active-bg: color-mix(in srgb, var(--accent-color) 28%, transparent);

  /* Tree Navigation Connector Lines & Items */
  --tree-line-color: color-mix(in srgb, var(--accent-color) 20%, var(--color-border));
  --tree-line-hover: color-mix(in srgb, var(--accent-color) 55%, var(--color-border));
  --tree-item-hover-bg: color-mix(in srgb, var(--accent-color) 8%, transparent);
  --tree-item-active-bg: color-mix(in srgb, var(--accent-color) 14%, transparent);
  --tree-item-active-text: var(--accent-color);

  /* Modal Backdrop & Overlays */
  --modal-backdrop-bg: rgba(25, 23, 20, 0.45);
  --overlay-bg: rgba(0, 0, 0, 0.2);
  --modal-shadow: 0 20px 40px -10px rgba(0, 0, 0, 0.16), 0 1px 3px rgba(0, 0, 0, 0.05);
  --drawer-shadow: none;

  /* ========================================================================
     DEFAULT PALETTE: BLACK & WHITE (LIGHT)
     Pure, clean monochrome aesthetic with high legibility and zero color tint
     ======================================================================== */
  --color-bg-body: #f8f8f9;
  --color-bg-surface: #ffffff;
  --color-bg-elevated: #ffffff;
  --color-border: #e2e2e5;
  --color-border-subtle: #ececef;
  --header-bg: rgba(255, 255, 255, 0.92);
  --header-border: #e2e2e5;
  --accent-color: #18181b;
  --accent-hover: #000000;
  --accent-ring: rgba(24, 24, 27, 0.25);
  --accent-contrast: #ffffff;
  --btn-subtle-bg: rgba(24, 24, 27, 0.05);
  --btn-subtle-border: rgba(24, 24, 27, 0.1);
  --btn-subtle-hover-bg: rgba(24, 24, 27, 0.09);
  --btn-subtle-hover-border: rgba(24, 24, 27, 0.16);
  --btn-subtle-active-bg: rgba(24, 24, 27, 0.14);
  --modal-bg: #ffffff;
  --modal-border: #e2e2e5;
  --drawer-bg: #ffffff;
  --drawer-border: #e2e2e5;
}

/* ==========================================================================
   DARK THEME BASE OVERRIDES
   ========================================================================== */
[data-theme="dark"] {
  --color-text-primary: #f5f2eb;
  --color-text-secondary: #a8a29e;
  --color-text-tertiary: #78716c;
  --btn-icon-color: #d6d3d1;
  --btn-icon-hover-color: #fafaf9;
  --modal-backdrop-bg: rgba(0, 0, 0, 0.65);
  --overlay-bg: rgba(0, 0, 0, 0.35);
  --modal-shadow: 0 20px 45px -10px rgba(0, 0, 0, 0.7);
  --drawer-shadow: none;

  /* Dynamic Header Action Buttons subtle theme backgrounds (Dark) */
  --header-btn-bg: color-mix(in srgb, var(--accent-color) 16%, transparent);
  --header-btn-border: color-mix(in srgb, var(--accent-color) 24%, transparent);
  --header-btn-hover-bg: color-mix(in srgb, var(--accent-color) 24%, transparent);
  --header-btn-hover-border: color-mix(in srgb, var(--accent-color) 36%, transparent);
  --header-btn-active-bg: color-mix(in srgb, var(--accent-color) 30%, transparent);

  /* Tree Navigation Connector Lines & Items (Dark) */
  --tree-line-color: color-mix(in srgb, var(--accent-color) 24%, var(--color-border));
  --tree-line-hover: color-mix(in srgb, var(--accent-color) 60%, var(--color-border));
  --tree-item-hover-bg: color-mix(in srgb, var(--accent-color) 12%, transparent);
  --tree-item-active-bg: color-mix(in srgb, var(--accent-color) 18%, transparent);
  --tree-item-active-text: var(--accent-color);

  /* DEFAULT DARK: BLACK & WHITE (MONOCHROME) */
  --color-bg-body: #121214;
  --color-bg-surface: #1a1a1d;
  --color-bg-elevated: #222226;
  --color-border: #2e2e34;
  --color-border-subtle: #242429;
  --header-bg: rgba(18, 18, 20, 0.9);
  --header-border: #28282e;
  --accent-color: #f4f4f5;
  --accent-hover: #ffffff;
  --accent-ring: rgba(244, 244, 245, 0.35);
  --accent-contrast: #121214;
  --btn-subtle-bg: rgba(244, 244, 245, 0.08);
  --btn-subtle-border: rgba(244, 244, 245, 0.14);
  --btn-subtle-hover-bg: rgba(244, 244, 245, 0.14);
  --btn-subtle-hover-border: rgba(244, 244, 245, 0.2);
  --btn-subtle-active-bg: rgba(244, 244, 245, 0.2);
  --modal-bg: #1a1a1d;
  --modal-border: #2e2e34;
  --drawer-bg: #1a1a1d;
  --drawer-border: #2e2e34;
}

/* ==========================================================================
   EXTRA DARK THEME BASE OVERRIDES (#121212)
   ========================================================================== */
[data-theme="extra-dark"] {
  --color-text-primary: #f5f5f5;
  --color-text-secondary: #a3a3a3;
  --color-text-tertiary: #737373;
  --btn-icon-color: #e5e5e5;
  --btn-icon-hover-color: #ffffff;
  --modal-backdrop-bg: rgba(0, 0, 0, 0.82);
  --overlay-bg: rgba(0, 0, 0, 0.55);
  --modal-shadow: 0 20px 50px -10px rgba(0, 0, 0, 0.92);
  --drawer-shadow: none;

  /* Dynamic Header Action Buttons subtle theme backgrounds */
  --header-btn-bg: color-mix(in srgb, var(--accent-color) 18%, transparent);
  --header-btn-border: color-mix(in srgb, var(--accent-color) 26%, transparent);
  --header-btn-hover-bg: color-mix(in srgb, var(--accent-color) 28%, transparent);
  --header-btn-hover-border: color-mix(in srgb, var(--accent-color) 40%, transparent);
  --header-btn-active-bg: color-mix(in srgb, var(--accent-color) 34%, transparent);

  /* Tree Navigation Connector Lines & Items */
  --tree-line-color: color-mix(in srgb, var(--accent-color) 26%, var(--color-border));
  --tree-line-hover: color-mix(in srgb, var(--accent-color) 65%, var(--color-border));
  --tree-item-hover-bg: color-mix(in srgb, var(--accent-color) 12%, transparent);
  --tree-item-active-bg: color-mix(in srgb, var(--accent-color) 20%, transparent);
  --tree-item-active-text: var(--accent-color);

  /* DEFAULT EXTRA DARK: PURE BLACK & WHITE */
  --color-bg-body: #000000;
  --color-bg-surface: #111113;
  --color-bg-elevated: #1a1a1e;
  --color-border: #26262b;
  --color-border-subtle: #1c1c20;
  --header-bg: rgba(0, 0, 0, 0.94);
  --header-border: #1f1f23;
  --accent-color: #ffffff;
  --accent-hover: #f4f4f5;
  --accent-ring: rgba(255, 255, 255, 0.4);
  --accent-contrast: #121214;
  --btn-subtle-bg: rgba(255, 255, 255, 0.09);
  --btn-subtle-border: rgba(255, 255, 255, 0.16);
  --btn-subtle-hover-bg: rgba(255, 255, 255, 0.16);
  --btn-subtle-hover-border: rgba(255, 255, 255, 0.24);
  --btn-subtle-active-bg: rgba(255, 255, 255, 0.24);
  --modal-bg: #111113;
  --modal-border: #26262b;
  --drawer-bg: #0d0d0f;
  --drawer-border: #1f1f23;
}

/* ==========================================================================
   PALETTE 0: DEFAULT (PURE BLACK & WHITE / MONOCHROME)
   Clean, distraction-free neutral aesthetic with pure black and white styling
   ========================================================================== */
[data-palette="default"] {
  --color-bg-body: #f8f8f9;
  --color-bg-surface: #ffffff;
  --color-bg-elevated: #ffffff;
  --color-border: #e2e2e5;
  --color-border-subtle: #ececef;
  --header-bg: rgba(255, 255, 255, 0.92);
  --header-border: #e2e2e5;
  --accent-color: #18181b;
  --accent-hover: #000000;
  --accent-ring: rgba(24, 24, 27, 0.25);
  --accent-contrast: #ffffff;
  --btn-subtle-bg: rgba(24, 24, 27, 0.05);
  --btn-subtle-border: rgba(24, 24, 27, 0.1);
  --btn-subtle-hover-bg: rgba(24, 24, 27, 0.09);
  --btn-subtle-hover-border: rgba(24, 24, 27, 0.16);
  --btn-subtle-active-bg: rgba(24, 24, 27, 0.14);
  --modal-bg: #ffffff;
  --modal-border: #e2e2e5;
  --drawer-bg: #ffffff;
  --drawer-border: #e2e2e5;
}

[data-palette="default"][data-theme="dark"],
[data-theme="dark"] [data-palette="default"] {
  --color-bg-body: #121214;
  --color-bg-surface: #1a1a1d;
  --color-bg-elevated: #222226;
  --color-border: #2e2e34;
  --color-border-subtle: #242429;
  --header-bg: rgba(18, 18, 20, 0.9);
  --header-border: #28282e;
  --accent-color: #f4f4f5;
  --accent-hover: #ffffff;
  --accent-ring: rgba(244, 244, 245, 0.35);
  --accent-contrast: #121214;
  --btn-subtle-bg: rgba(244, 244, 245, 0.08);
  --btn-subtle-border: rgba(244, 244, 245, 0.14);
  --btn-subtle-hover-bg: rgba(244, 244, 245, 0.14);
  --btn-subtle-hover-border: rgba(244, 244, 245, 0.2);
  --btn-subtle-active-bg: rgba(244, 244, 245, 0.2);
  --modal-bg: #1a1a1d;
  --modal-border: #2e2e34;
  --drawer-bg: #1a1a1d;
  --drawer-border: #2e2e34;
}

[data-palette="default"][data-theme="extra-dark"],
[data-theme="extra-dark"] [data-palette="default"] {
  --color-bg-body: #000000;
  --color-bg-surface: #111113;
  --color-bg-elevated: #1a1a1e;
  --color-border: #26262b;
  --color-border-subtle: #1c1c20;
  --header-bg: rgba(0, 0, 0, 0.94);
  --header-border: #1f1f23;
  --accent-color: #ffffff;
  --accent-hover: #f4f4f5;
  --accent-ring: rgba(255, 255, 255, 0.4);
  --accent-contrast: #121214;
  --btn-subtle-bg: rgba(255, 255, 255, 0.09);
  --btn-subtle-border: rgba(255, 255, 255, 0.16);
  --btn-subtle-hover-bg: rgba(255, 255, 255, 0.16);
  --btn-subtle-hover-border: rgba(255, 255, 255, 0.24);
  --btn-subtle-active-bg: rgba(255, 255, 255, 0.24);
  --modal-bg: #111113;
  --modal-border: #26262b;
  --drawer-bg: #0d0d0f;
  --drawer-border: #1f1f23;
}

/* ==========================================================================
   PALETTE 1: BEIGE (EXPLICIT)
   ========================================================================== */
[data-palette="beige"] {
  --color-bg-body: #f7f4ee;
  --color-bg-surface: #ffffff;
  --color-bg-elevated: #fbf8f3;
  --color-border: #e6dfd4;
  --color-border-subtle: #efe9df;
  --header-bg: rgba(247, 244, 238, 0.88);
  --header-border: #e5dfd4;
  --accent-color: #7d6350;
  --accent-hover: #695240;
  --accent-ring: rgba(125, 99, 80, 0.3);
  --btn-subtle-bg: rgba(125, 99, 80, 0.06);
  --btn-subtle-border: rgba(125, 99, 80, 0.1);
  --btn-subtle-hover-bg: rgba(125, 99, 80, 0.11);
  --btn-subtle-hover-border: rgba(125, 99, 80, 0.16);
  --btn-subtle-active-bg: rgba(125, 99, 80, 0.15);
  --modal-bg: #fcfaf6;
  --modal-border: #e6dfd4;
  --drawer-bg: #fcfaf6;
  --drawer-border: #e6dfd4;
}

[data-palette="beige"][data-theme="dark"],
[data-theme="dark"] [data-palette="beige"] {
  --color-bg-body: #181613;
  --color-bg-surface: #201e19;
  --color-bg-elevated: #28251f;
  --color-border: #332d25;
  --color-border-subtle: #29241d;
  --header-bg: rgba(24, 22, 19, 0.88);
  --header-border: #2f2a22;
  --accent-color: #d8c3b0;
  --accent-hover: #eddcd0;
  --accent-ring: rgba(216, 195, 176, 0.35);
  --btn-subtle-bg: rgba(216, 195, 176, 0.08);
  --btn-subtle-border: rgba(216, 195, 176, 0.12);
  --btn-subtle-hover-bg: rgba(216, 195, 176, 0.13);
  --btn-subtle-hover-border: rgba(216, 195, 176, 0.18);
  --btn-subtle-active-bg: rgba(216, 195, 176, 0.18);
  --modal-bg: #201e19;
  --modal-border: #332d25;
  --drawer-bg: #201e19;
  --drawer-border: #332d25;
}

[data-palette="beige"][data-theme="extra-dark"],
[data-theme="extra-dark"] [data-palette="beige"] {
  --color-bg-body: #121212;
  --color-bg-surface: #1c1a18;
  --color-bg-elevated: #24221e;
  --color-border: #2f2a24;
  --color-border-subtle: #23201a;
  --header-bg: rgba(18, 18, 18, 0.92);
  --header-border: #2a251e;
  --accent-color: #e0cfc0;
  --accent-hover: #f0e2d5;
  --accent-ring: rgba(224, 207, 192, 0.35);
  --btn-subtle-bg: rgba(224, 207, 192, 0.08);
  --btn-subtle-border: rgba(224, 207, 192, 0.14);
  --btn-subtle-hover-bg: rgba(224, 207, 192, 0.14);
  --btn-subtle-hover-border: rgba(224, 207, 192, 0.2);
  --btn-subtle-active-bg: rgba(224, 207, 192, 0.2);
  --modal-bg: #1c1a18;
  --modal-border: #2f2a24;
  --drawer-bg: #181715;
  --drawer-border: #2a251e;
}

/* Responsive Page Gutters: snug edge-to-edge layout with balanced margins */
@media (min-width: 640px) {
  :root {
    --page-gutter: 12px;
  }
}

@media (min-width: 1024px) {
  :root {
    --page-gutter: 14px;
  }
}

@media (min-width: 1440px) {
  :root {
    --page-gutter: 16px;
  }
}

/* ==========================================================================
   PALETTE 2: GREEN (Subtle Sage / Eucalyptus)
   ========================================================================== */
[data-palette="green"] {
  --color-bg-body: #f2f6f3;
  --color-bg-surface: #ffffff;
  --color-bg-elevated: #f7fbf8;
  --color-border: #dae6df;
  --color-border-subtle: #e6f0ea;
  --header-bg: rgba(242, 246, 243, 0.88);
  --header-border: #d6e3db;
  --accent-color: #2c7250;
  --accent-hover: #225c40;
  --accent-ring: rgba(44, 114, 80, 0.3);
  --btn-subtle-bg: rgba(44, 114, 80, 0.06);
  --btn-subtle-border: rgba(44, 114, 80, 0.1);
  --btn-subtle-hover-bg: rgba(44, 114, 80, 0.11);
  --btn-subtle-hover-border: rgba(44, 114, 80, 0.16);
  --btn-subtle-active-bg: rgba(44, 114, 80, 0.15);
  --modal-bg: #f8faf8;
  --modal-border: #dae6df;
  --drawer-bg: #f8faf8;
  --drawer-border: #dae6df;
}

[data-palette="green"][data-theme="dark"],
[data-theme="dark"] [data-palette="green"] {
  --color-bg-body: #121915;
  --color-bg-surface: #1a231e;
  --color-bg-elevated: #212d26;
  --color-border: #27372e;
  --color-border-subtle: #1e2c24;
  --header-bg: rgba(18, 25, 21, 0.88);
  --header-border: #25342b;
  --accent-color: #9cd2b4;
  --accent-hover: #bde4ce;
  --accent-ring: rgba(156, 210, 180, 0.35);
  --btn-subtle-bg: rgba(156, 210, 180, 0.08);
  --btn-subtle-border: rgba(156, 210, 180, 0.12);
  --btn-subtle-hover-bg: rgba(156, 210, 180, 0.13);
  --btn-subtle-hover-border: rgba(156, 210, 180, 0.18);
  --btn-subtle-active-bg: rgba(156, 210, 180, 0.18);
  --modal-bg: #1a231e;
  --modal-border: #27372e;
  --drawer-bg: #1a231e;
  --drawer-border: #27372e;
}

[data-palette="green"][data-theme="extra-dark"],
[data-theme="extra-dark"] [data-palette="green"] {
