  --header-bg: rgba(18, 18, 18, 0.92);
  --header-border: #222e27;
  --accent-color: #9cd2b4;
  --accent-hover: #bde4ce;
  --accent-ring: rgba(156, 210, 180, 0.35);
  --btn-subtle-bg: rgba(156, 210, 180, 0.08);
  --btn-subtle-border: rgba(156, 210, 180, 0.14);
  --btn-subtle-hover-bg: rgba(156, 210, 180, 0.14);
  --btn-subtle-hover-border: rgba(156, 210, 180, 0.2);
  --btn-subtle-active-bg: rgba(156, 210, 180, 0.2);
  --modal-bg: #161c18;
  --modal-border: #26332b;
  --drawer-bg: #141916;
  --drawer-border: #222e27;
}

/* ==========================================================================
   PALETTE 3: ORANGE (Subtle Peach / Apricot)
   ========================================================================== */
[data-palette="orange"] {
