  --color-bg-surface: #ffffff;
  --color-bg-elevated: #fdf8f3;
  --color-border: #eadfcf;
  --color-border-subtle: #f3eae0;
  --header-bg: rgba(249, 244, 238, 0.88);
  --header-border: #e6dac8;
  --accent-color: #b85b20;
  --accent-hover: #9c4c19;
  --accent-ring: rgba(184, 91, 32, 0.3);
  --btn-subtle-bg: rgba(184, 91, 32, 0.06);
  --btn-subtle-border: rgba(184, 91, 32, 0.1);
  --btn-subtle-hover-bg: rgba(184, 91, 32, 0.11);
  --btn-subtle-hover-border: rgba(184, 91, 32, 0.16);
  --btn-subtle-active-bg: rgba(184, 91, 32, 0.15);
  --modal-bg: #fdfaf6;
