  --color-border: #392525;
  --color-border-subtle: #2d1c1c;
  --header-bg: rgba(26, 19, 19, 0.88);
  --header-border: #331f1f;
  --accent-color: #f19696;
  --accent-hover: #f9bebe;
  --accent-ring: rgba(241, 150, 150, 0.35);
  --btn-subtle-bg: rgba(241, 150, 150, 0.08);
  --btn-subtle-border: rgba(241, 150, 150, 0.12);
  --btn-subtle-hover-bg: rgba(241, 150, 150, 0.13);
  --btn-subtle-hover-border: rgba(241, 150, 150, 0.18);
  --btn-subtle-active-bg: rgba(241, 150, 150, 0.18);
  --modal-bg: #241818;
  --modal-border: #392525;
  --drawer-bg: #241818;
  --drawer-border: #392525;
}

[data-palette="red"][data-theme="extra-dark"],
[data-theme="extra-dark"] [data-palette="red"] {
  --color-bg-body: #121212;
  --color-bg-surface: #1e1616;
  --color-bg-elevated: #271c1c;
  --color-border: #362323;
  --color-border-subtle: #281919;
  --header-bg: rgba(18, 18, 18, 0.92);
  --header-border: #301e1e;
  --accent-color: #f19696;
  --accent-hover: #f9bebe;
  --accent-ring: rgba(241, 150, 150, 0.35);
  --btn-subtle-bg: rgba(241, 150, 150, 0.08);
  --btn-subtle-border: rgba(241, 150, 150, 0.14);
  --btn-subtle-hover-bg: rgba(241, 150, 150, 0.14);
  --btn-subtle-hover-border: rgba(241, 150, 150, 0.2);
  --btn-subtle-active-bg: rgba(241, 150, 150, 0.2);
  --modal-bg: #1e1616;
  --modal-border: #362323;
  --drawer-bg: #181313;
  --drawer-border: #301e1e;
}

/* --------------------------------------------------------------------------
   Global Reset
   -------------------------------------------------------------------------- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

html {
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
  color-scheme: light dark;
}

/* --------------------------------------------------------------------------
   Hide Vertical Scrollbars across Website while preserving smooth scrolling
   -------------------------------------------------------------------------- */
html,
body {
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* IE and Edge */
}

html::-webkit-scrollbar,
body::-webkit-scrollbar,
::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  background: transparent !important;
}

body {
  font-family: var(--font-family-base);
  background-color: var(--color-bg-body);
  color: var(--color-text-primary);
  min-height: 100vh;
  overflow-x: hidden;
}

/* Prevent background scrolling without causing layout shifts */
body.modal-open,
body.nav-drawer-open {
  overflow-y: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

/* --------------------------------------------------------------------------
   Focus Outline Reset & Custom Focus Rings
   -------------------------------------------------------------------------- */
*:focus {
  outline: none !important;
}

button:focus,
input:focus,
a:focus,
[tabindex]:focus {
  outline: none !important;
}

/* Subtle, site-accent-consistent custom focus ring for keyboard accessibility */
*:focus-visible {
  outline: none !important;
  box-shadow: 0 0 0 2px var(--color-bg-body), 0 0 0 4px var(--accent-ring) !important;
}

/* Suppress browser native autocomplete/autofill bluish background tint */
input:-webkit-autofill,
input:-webkit-autofill:hover, 
input:-webkit-autofill:focus, 
input:-webkit-autofill:active {
  -webkit-box-shadow: 0 0 0 1000px var(--color-bg-surface) inset !important;
  box-shadow: 0 0 0 1000px var(--color-bg-surface) inset !important;
  -webkit-text-fill-color: var(--color-text-primary) !important;
  caret-color: var(--color-text-primary) !important;
  transition: background-color 5000s ease-in-out 0s;
}

[data-theme="dark"] input:-webkit-autofill,
[data-theme="dark"] input:-webkit-autofill:hover, 
[data-theme="dark"] input:-webkit-autofill:focus, 
[data-theme="dark"] input:-webkit-autofill:active,
.dark input:-webkit-autofill,
.dark input:-webkit-autofill:hover, 
.dark input:-webkit-autofill:focus, 
.dark input:-webkit-autofill:active {
  -webkit-box-shadow: 0 0 0 1000px var(--color-bg-surface, #1e293b) inset !important;
  box-shadow: 0 0 0 1000px var(--color-bg-surface, #1e293b) inset !important;
  -webkit-text-fill-color: var(--color-text-primary, #f5f2eb) !important;
  caret-color: var(--color-text-primary, #f5f2eb) !important;
}


/* Exclude search inputs, fields, and share modal link input from any focus rings or focus borders */
input[type="search"]:focus,
input[type="search"]:focus-visible,
.search-modal-input,
.search-modal-input:focus,
.search-modal-input:focus-visible,
.search-modal-field,
.search-modal-field:focus,
.search-modal-field:focus-within,
.search-modal-field:focus-visible,
.share-copy-box,
.share-copy-box:focus,
.share-copy-box:focus-within,
.share-copy-box:focus-visible,
.share-url-input,
.share-url-input:focus,
.share-url-input:focus-within,
.share-url-input:focus-visible,
.share-url-input:active {
  outline: none !important;
  outline-offset: 0 !important;
  box-shadow: none !important;
  -webkit-box-shadow: none !important;
}

button {
  font-family: inherit;
  font-size: inherit;
  background: none;
  border: none;
  cursor: pointer;
  color: inherit;
}

input {
  font-family: inherit;
  font-size: inherit;
}

/* Monospace Elements: Standardized on Geist Mono */
code,
kbd,
samp,
pre {
  font-family: var(--font-family-mono);
}

/* Global Text Highlight / Mark with minimal footprint & high contrast */
mark,
.highlight {
  background-color: #fef08a;
  color: #1c1917;
  padding: 0.1em 0.3em;
  border-radius: 2px;
  font-size: inherit;
  font-weight: inherit;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
  border: none;
}

[data-theme="dark"] mark,
[data-theme="dark"] .highlight,
[data-theme="extra-dark"] mark,
[data-theme="extra-dark"] .highlight {
  background-color: rgba(250, 204, 21, 0.25);
  color: #fef08a;
  border: none;
}

/* Standard Blockquote: Simple editorial design with subtle left line only, no div/box background */
blockquote {
  margin: 24px 0;
  padding: 4px 0 4px 18px;
  border-left: 2px solid var(--color-border);
  border-top: none;
  border-right: none;
  border-bottom: none;
  background: transparent;
  background-color: transparent;
  border-radius: 0;
  box-shadow: none;
  font-style: italic;
  color: var(--color-text-secondary);
}

blockquote p {
  margin: 0;
  color: inherit;
  font-style: inherit;
}

blockquote p + p {
  margin-top: 12px;
}

/* --------------------------------------------------------------------------
   Global Helper Utilities
   -------------------------------------------------------------------------- */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* --------------------------------------------------------------------------
   Universal Themed Text Selection (Standard & Mozilla Firefox ::-moz-selection)
   Replaces default browser blue with active theme palette accent for every theme
   -------------------------------------------------------------------------- */
::selection,
*::selection {
  background-color: var(--accent-color);
  color: #ffffff;
}

::-moz-selection,
*::-moz-selection {
  background-color: var(--accent-color);
  color: #ffffff;
}

[data-theme="dark"] ::selection,
[data-theme="dark"] *::selection,
[data-theme="extra-dark"] ::selection,
[data-theme="extra-dark"] *::selection {
  background-color: var(--accent-color);
  color: #121212;
}

[data-theme="dark"] ::-moz-selection,
[data-theme="dark"] *::-moz-selection,
[data-theme="extra-dark"] ::-moz-selection,
[data-theme="extra-dark"] *::-moz-selection {
  background-color: var(--accent-color);
  color: #121212;
}

/* --------------------------------------------------------------------------
   Universal Minimal Alerts System (Info, Warning, Success, Error)
   Pixel-accurate matching the clean rounded card, colored badge, stem line & text
   -------------------------------------------------------------------------- */
.alert {
  position: relative;
  display: block;
  border-radius: 8px;
  padding: 16px 20px 18px 20px;
  margin: 20px 0;
  box-sizing: border-box;
  border: 1px solid transparent;
  font-family: inherit;
  transition: background-color 0.2s ease, border-color 0.2s ease;
}

.alert-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 7px;
}

.alert-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}

.alert-icon svg {
  width: 18px;
  height: 18px;
  display: block;
}

.alert-title {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.01em;
}

.alert-body {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 0;
}

.alert-stem {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  width: 18px;
  flex-shrink: 0;
  padding-top: 2px;
}

.alert-stem::after {
  content: "";
  display: block;
  width: 1.5px;
  height: 15px;
  background-color: currentColor;
  opacity: 0.65;
  border-radius: 1px;
}

.alert-message,
.alert-text {
  flex: 1;
  margin: 0;
  font-size: 14px;
  line-height: 1.55;
}

/* Fallback for simple markup: <div class="alert"><div class="alert-header">...</div><p>...</p></div> */
.alert > p:not(.alert-body) {
  position: relative;
  margin: 0;
  padding-left: 28px;
  font-size: 14px;
  line-height: 1.55;
}

.alert > p:not(.alert-body)::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 3px;
  width: 1.5px;
  height: 15px;
  background-color: currentColor;
  opacity: 0.65;
  border-radius: 1px;
}

/* 1. INFO ALERT (Soft blue card, solid sky-blue badge, rich blue text) */
.alert-info,
.alert.alert-info {
  background-color: #eaf1f8;
  color: #2b5c8f;
  border-color: rgba(43, 92, 143, 0.08);
}
.alert-info .alert-title {
  color: #244e7c;
}
.alert-info .alert-icon {
  color: #0284c7;
}
.alert-info .alert-stem {
  color: #2b5c8f;
}
.alert-info .alert-message,
.alert-info .alert-text,
.alert-info > p {
  color: #356598;
}

/* 2. WARNING ALERT (Warm cream-amber card, amber badge, golden-brown text) */
.alert-warning,
.alert.alert-warning {
  background-color: #f6f1e7;
  color: #8c6b24;
  border-color: rgba(140, 107, 36, 0.08);
}
.alert-warning .alert-title {
  color: #785a19;
}
.alert-warning .alert-icon {
  color: #d97706;
}
.alert-warning .alert-stem {
  color: #8c6b24;
}
.alert-warning .alert-message,
.alert-warning .alert-text,
.alert-warning > p {
  color: #8c6b24;
}

/* 3. SUCCESS ALERT (Soft mint sage card, emerald badge, forest green text) */
.alert-success,
.alert.alert-success {
  background-color: #e8f2ee;
  color: #1b6b4a;
  border-color: rgba(27, 107, 74, 0.08);
}
.alert-success .alert-title {
  color: #14563b;
}
.alert-success .alert-icon {
  color: #10b981;
}
.alert-success .alert-stem {
  color: #1b6b4a;
}
.alert-success .alert-message,
.alert-success .alert-text,
.alert-success > p {
  color: #237352;
}

/* 4. ERROR / DANGER ALERT (Soft pastel rose card, coral/rose badge, crimson text) */
.alert-error,
.alert-danger,
.alert.alert-error,
.alert.alert-danger {
  background-color: #f9e9ec;
  color: #a8233c;
  border-color: rgba(168, 35, 60, 0.08);
}
.alert-error .alert-title,
.alert-danger .alert-title {
  color: #921c32;
}
.alert-error .alert-icon,
.alert-danger .alert-icon {
  color: #e11d48;
}
.alert-error .alert-stem,
.alert-danger .alert-stem {
  color: #a8233c;
}
.alert-error .alert-message,
.alert-error .alert-text,
.alert-error > p,
.alert-danger .alert-message,
.alert-danger .alert-text,
.alert-danger > p {
  color: #b82e48;
}

/* Dark & Extra-Dark Mode Adaptations for High Contrast & Eye Comfort */
[data-theme="dark"] .alert-info,
[data-theme="extra-dark"] .alert-info {
  background-color: rgba(14, 165, 233, 0.12);
  border-color: rgba(56, 189, 248, 0.25);
