}
[data-theme="dark"] .alert-warning .alert-message,
[data-theme="dark"] .alert-warning .alert-text,
[data-theme="dark"] .alert-warning > p,
[data-theme="extra-dark"] .alert-warning .alert-message,
[data-theme="extra-dark"] .alert-warning .alert-text,
