// Aliases for type lookups
ICONS.success = ICONS.tick;
ICONS.error = ICONS.cross;
ICONS.warn = ICONS.warning;
ICONS.online = ICONS.wifi;
ICONS.network = ICONS.wifi;
ICONS.offline = ICONS["no-network"];
ICONS.nowifi = ICONS["no-network"];
ICONS["wifi-off"] = ICONS["no-network"];
ICONS.help = ICONS.question;
ICONS.trash = ICONS.delete;

/**
 * Modern tactile swipe-to-close with elastic rubber band resistance.
 * - PC: User can only swipe RIGHT to dismiss. Swiping LEFT creates an elastic rubber band effect and snaps back.
 * - Mobile: User can swipe UP, LEFT, and RIGHT to dismiss. Swiping DOWN creates an elastic rubber band effect and snaps back.
 */
function setupSwipeGestures(toast, onDismiss, onPauseTimer, onResumeTimer) {
  let isDragging = false;
  let startX = 0;
  let startY = 0;
  let currentDeltaX = 0;
  let currentDeltaY = 0;
  let activePointerId = null;

  // Elastic damper calculation (asymptotic soft resistance towards maxStretch)
  function calculateElastic(delta, maxStretch = 34) {
    const sign = delta < 0 ? -1 : 1;
    const abs = Math.abs(delta);
    const stretch = maxStretch * (1 - Math.exp(-abs / (maxStretch * 2.2)));
    return sign * stretch;
  }

  function handlePointerDown(e) {
    if (e.button !== 0 && e.pointerType === 'mouse') return;
    isDragging = true;
    activePointerId = e.pointerId;
    startX = e.clientX;
    startY = e.clientY;
    currentDeltaX = 0;
    currentDeltaY = 0;

    toast.classList.add("is-swiping");
    toast.style.transition = "none";
    if (toast.setPointerCapture) {
      try {
        toast.setPointerCapture(e.pointerId);
      } catch (err) {}
    }

    if (typeof onPauseTimer === 'function') onPauseTimer();
  }

  function handlePointerMove(e) {
    if (!isDragging || e.pointerId !== activePointerId) return;

    const rawDeltaX = e.clientX - startX;
    const rawDeltaY = e.clientY - startY;
    const isMobile = window.innerWidth <= 768 || e.pointerType === 'touch';

    let displayX = 0;
    let displayY = 0;
    let opacity = 1;

    if (!isMobile) {
      // -------------------------------------------------------------
      // PC / Desktop: User can ONLY swipe RIGHT to close.
      // Left swipe triggers an elastic rubber band effect and never dismisses.
      // -------------------------------------------------------------
      if (rawDeltaX > 0) {
        displayX = rawDeltaX;
        opacity = Math.max(0.2, 1 - (rawDeltaX / 300));
      } else {
        displayX = calculateElastic(rawDeltaX, 35);
        opacity = 1;
      }
      displayY = 0;
    } else {
      // -------------------------------------------------------------
      // Mobile: User can swipe UP, LEFT, and RIGHT to close.
      // DOWN swipe triggers an elastic rubber band effect and never dismisses.
      // -------------------------------------------------------------
      const absX = Math.abs(rawDeltaX);
      const absY = Math.abs(rawDeltaY);

      if (absX >= absY) {
        // Horizontal swipe (LEFT or RIGHT) - both dismiss on mobile
        displayX = rawDeltaX;
        opacity = Math.max(0.2, 1 - (absX / 280));
        displayY = rawDeltaY < 0 ? rawDeltaY * 0.2 : calculateElastic(rawDeltaY, 14);
      } else {
        // Vertical swipe
        displayX = rawDeltaX * 0.25;
        if (rawDeltaY < 0) {
          // Swiping UP (dismissible)
          displayY = rawDeltaY;
          opacity = Math.max(0.2, 1 - (absY / 220));
        } else {
          // Swiping DOWN (elastic rubber band effect)
          displayY = calculateElastic(rawDeltaY, 35);
          opacity = 1;
        }
      }
    }

    currentDeltaX = rawDeltaX;
    currentDeltaY = rawDeltaY;

    toast.style.transform = `translate3d(${displayX.toFixed(1)}px, ${displayY.toFixed(1)}px, 0)`;
    toast.style.opacity = opacity.toFixed(2);
  }

  function handlePointerUp(e) {
    if (!isDragging || e.pointerId !== activePointerId) return;
    isDragging = false;
    activePointerId = null;
    toast.classList.remove("is-swiping");

    if (toast.releasePointerCapture) {
      try {
        toast.releasePointerCapture(e.pointerId);
      } catch (err) {}
    }

    const isMobile = window.innerWidth <= 768 || e.pointerType === 'touch';
    const THRESHOLD_X = isMobile ? 65 : 75;
    const THRESHOLD_Y = 55;

    let shouldDismiss = false;
    let dismissDirection = null;

    if (!isMobile) {
      // PC: ONLY dismiss if swiped RIGHT past threshold
      if (currentDeltaX > THRESHOLD_X) {
        shouldDismiss = true;
        dismissDirection = "right";
      }
    } else {
      // Mobile: Dismiss if swiped RIGHT, LEFT, or UP past threshold. NEVER down!
      const absX = Math.abs(currentDeltaX);
      const absY = Math.abs(currentDeltaY);

      if (absX >= absY) {
        if (currentDeltaX > THRESHOLD_X) {
          shouldDismiss = true;
          dismissDirection = "right";
        } else if (currentDeltaX < -THRESHOLD_X) {
          shouldDismiss = true;
          dismissDirection = "left";
        }
      } else {
        if (currentDeltaY < -THRESHOLD_Y) {
          shouldDismiss = true;
          dismissDirection = "up";
        }
      }
    }

    if (shouldDismiss && dismissDirection) {
      toast.style.transition = "transform 0.22s cubic-bezier(0.2, 0, 0, 1), opacity 0.2s ease";
      if (dismissDirection === "right") {
        toast.style.transform = "translate3d(130%, 0, 0)";
      } else if (dismissDirection === "left") {
        toast.style.transform = "translate3d(-130%, 0, 0)";
      } else if (dismissDirection === "up") {
        toast.style.transform = "translate3d(0, -130%, 0)";
      }
      toast.style.opacity = "0";

      setTimeout(() => {
        if (typeof onDismiss === 'function') onDismiss();
      }, 200);
    } else {
      // Elastic snap back with spring overshoot curve
      toast.style.transition = "transform 0.36s cubic-bezier(0.175, 0.885, 0.32, 1.275), opacity 0.24s ease";
      toast.style.transform = "translate3d(0, 0, 0)";
      toast.style.opacity = "1";

      setTimeout(() => {
        if (!isDragging) {
          toast.style.transition = "";
          toast.style.transform = "";
          toast.style.opacity = "";
        }
      }, 380);

      if (typeof onResumeTimer === 'function') onResumeTimer();
    }
  }

  function handlePointerCancel(e) {
    if (isDragging) {
      handlePointerUp(e);
    }
  }

  toast.addEventListener("pointerdown", handlePointerDown);
  toast.addEventListener("pointermove", handlePointerMove);
  toast.addEventListener("pointerup", handlePointerUp);
  toast.addEventListener("pointercancel", handlePointerCancel);
}

/**
 * Global showToast function with deduplication and active stack management
 * @param {string} message - Message text
 * @param {string} [type="success"] - "success"|"tick"|"error"|"cross"|"warning"|"info"|"question"|"delete"|"wifi"|"no-network"|"loading"|"copy"
 * @param {number} [duration=8000] - Auto-dismiss delay in ms (0 for infinite)
 * @param {string} [id=`${type}:${message}`] - Unique key for deduplication
 */
function showToast(
  message,
  type = "success",
  duration = 8000,
  id = `${type}:${message}`
) {
  if (!message && message !== 0) return null;

  // Normalize type
  const normalizedType = String(type || "success").toLowerCase().trim();

  // Auto-resolve or create container element
  let container = document.getElementById("toast-container");
  if (!container) {
    if (typeof document === "undefined" || !document.body) {
      if (typeof window !== "undefined") {
        window.addEventListener("DOMContentLoaded", () => showToast(message, type, duration, id));
      }
      return null;
    }
    container = document.createElement("div");
    container.id = "toast-container";
    document.body.appendChild(container);
  }

  // Reuse / update existing active toast if key already exists (prevents duplicate spamming)
  if (activeToasts.has(id)) {
    const existing = activeToasts.get(id);
    existing.update(message, normalizedType, duration);
    return existing;
  }

  // Stacking prevention: limit maximum simultaneous active toasts to 4
  if (activeToasts.size >= 4) {
    const oldestKey = activeToasts.keys().next().value;
    const oldestToast = activeToasts.get(oldestKey);
    if (oldestToast && typeof oldestToast.dismiss === "function") {
      oldestToast.dismiss();
    }
  }

  const toast = document.createElement("div");
  toast.className = `toast ${normalizedType}`;

  function render(text, toastType) {
    const safeType = String(toastType || "success").toLowerCase().trim();
    toast.className = `toast ${safeType}`;
    const iconHtml = ICONS[safeType] || ICONS.success;
    toast.innerHTML = `
      <i>${iconHtml}</i>
      <span>${escapeHtml(String(text))}</span>
    `;
  }

  render(message, normalizedType);
  container.appendChild(toast);

  let timer;
  let remaining = duration;
  let startedAt = Date.now();

  function dismiss(delay = duration) {
    clearTimeout(timer);
    if (delay === 0) {
      activeToasts.delete(id);
      if (toast.parentNode) {
        toast.remove();
      }
      return;
    }

    timer = setTimeout(() => {
      activeToasts.delete(id);
      toast.classList.add("hide");
      toast.addEventListener(
        "animationend",
        () => {
          if (toast.parentNode) {
            toast.remove();
          }
        },
        { once: true }
      );
    }, delay);
  }

  dismiss();

  // Pause on hover
  if (duration > 0) {
    toast.addEventListener("mouseenter", () => {
      clearTimeout(timer);
      const elapsed = Date.now() - startedAt;
      remaining = Math.max(0, remaining - elapsed);
    });

    toast.addEventListener("mouseleave", () => {
      startedAt = Date.now();
      dismiss(remaining);
    });
  }

  // Setup modern swipe-to-close with elastic rubber band gestures
  setupSwipeGestures(
    toast,
    () => {
      // Swipe dismissed
      dismiss(0);
    },
    () => {
      // Pause timer while dragging
      clearTimeout(timer);
      const elapsed = Date.now() - startedAt;
      remaining = Math.max(0, remaining - elapsed);
    },
    () => {
      // Resume timer on release if not dismissed
      startedAt = Date.now();
      dismiss(remaining);
    }
  );

  const api = {
    element: toast,
    update(newMessage, newType = "success", newDuration = 8000) {
      render(newMessage, newType);
      toast.classList.remove("hide");
      remaining = newDuration;
      startedAt = Date.now();
      dismiss(newDuration);
      return api;
    },
    dismiss() {
      clearTimeout(timer);
      activeToasts.delete(id);
      toast.classList.add("hide");
      toast.addEventListener(
        "animationend",
        () => {
          if (toast.parentNode) {
            toast.remove();
          }
        },
        { once: true }
      );
    }
  };

  activeToasts.set(id, api);
  return api;
}

function escapeHtml(str) {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

// Convenience object API
const Toast = {
  show: showToast,
  success: (msg, dur, id) => showToast(msg, "success", dur, id),
  tick: (msg, dur, id) => showToast(msg, "tick", dur, id),
  error: (msg, dur, id) => showToast(msg, "error", dur, id),
  cross: (msg, dur, id) => showToast(msg, "cross", dur, id),
  warning: (msg, dur, id) => showToast(msg, "warning", dur, id),
  info: (msg, dur, id) => showToast(msg, "info", dur, id),
  question: (msg, dur, id) => showToast(msg, "question", dur, id),
  delete: (msg, dur, id) => showToast(msg, "delete", dur, id),
  wifi: (msg, dur, id) => showToast(msg, "wifi", dur, id),
  online: (msg, dur, id) => showToast(msg, "online", dur, id),
  offline: (msg, dur, id) => showToast(msg, "offline", dur, id),
  noNetwork: (msg, dur, id) => showToast(msg, "no-network", dur, id),
  loading: (msg, dur, id) => showToast(msg, "loading", dur, id),
  copy: (msg, dur, id) => showToast(msg, "copy", dur, id)
};

// Global Attachments for Browser Environment
if (typeof window !== "undefined") {
  window.activeToasts = activeToasts;
  window.showToast = showToast;
  window.Toast = Toast;
  window.AppToast = Toast;

  function bindAuthToast() {
    if (window.RadiologyAuth) {
      window.RadiologyAuth.showToast = function (message, type = "info") {
        return showToast(message, type);
      };
    }
  }
  bindAuthToast();
  window.addEventListener("DOMContentLoaded", bindAuthToast);
}

// ES module / CommonJS export support
if (typeof exports !== "undefined") {
  exports.activeToasts = activeToasts;
  exports.showToast = showToast;
  exports.Toast = Toast;
}


/**
 * COOKIE AUTH & WORKSPACE ENGINE
 * Clinical Radiology Guide - Universal Auth & Storage Controller
 * 
 * Architecture:
 * 1. Anonymous First: Users can use the website without an account.
 *    - Save bookmarks locally (cookies & localStorage)
 *    - Track download history locally
 *    - Save theme and local preferences
 *    - No complicated "Local Account" terminology - simply browser storage
 * 2. Optional Google Authentication:
 *    - Cross-device synchronization of bookmarks, downloads, and preferences
 *    - Merges local data into Google account without overwriting or duplicates
 *    - Required ONLY for identity features (commenting)
 * 3. Theme Synchronization:
 *    - Current local theme is preserved upon Google sign-in
 *    - Local theme remains intact upon sign-out
 */

(function () {
  'use strict';

  // Cookie Names
  const COOKIE_SESSION = 'radiology_session';
  const COOKIE_BOOKMARKS = 'radiology_bookmarks';

  // Storage Keys
  const STORAGE_SESSION = 'my_radiology_user_session';
  const STORAGE_BOOKMARKS_PRIMARY = 'radiology_saved_posts';
  const STORAGE_BOOKMARKS_SECONDARY = 'radiology_saved_protocols';
  const STORAGE_DOWNLOADS = 'radiology_downloads_history_v1';
  const STORAGE_COMMENTS = 'radiology_post_comments_v1';
  const STORAGE_STREAK = 'radiology_study_streak';
  const STORAGE_THEME = 'app-theme-preference';

  // Cookie Utilities
  function setCookie(name, value, days = 365) {
    try {
      const d = new Date();
      d.setTime(d.getTime() + days * 24 * 60 * 60 * 1000);
      const expires = 'expires=' + d.toUTCString();
      const stringValue = typeof value === 'object' ? JSON.stringify(value) : String(value);
      const encoded = encodeURIComponent(stringValue);
      document.cookie = `${name}=${encoded}; ${expires}; path=/; SameSite=Lax`;
    } catch (e) {
      console.warn('Cookie set error:', e);
    }
  }

  function getCookie(name) {
    try {
      const nameEQ = name + '=';
      const ca = document.cookie.split(';');
      for (let i = 0; i < ca.length; i++) {
        let c = ca[i].trim();
        if (c.indexOf(nameEQ) === 0) {
          const raw = decodeURIComponent(c.substring(nameEQ.length));
          try {
            return JSON.parse(raw);
          } catch {
            return raw;
          }
        }
      }
    } catch (e) {
      console.warn('Cookie read error:', e);
    }
    return null;
  }

  function deleteCookie(name) {
    document.cookie = `${name}=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/; SameSite=Lax`;
  }

  /* ==========================================================================
     BOOKMARK MANAGEMENT (Browser Storage - Works Anonymously)
     ========================================================================== */

  const DEFAULT_INITIAL_BOOKMARKS = [
    'stroke-cta-protocol',
    'chest-hrct-interstitial',
    'physics-tube-rating'
  ];

  function getBookmarks() {
    let ids = [];

    // 1. Try reading from cookie first
    const cookieData = getCookie(COOKIE_BOOKMARKS);
    if (Array.isArray(cookieData)) {
      ids = cookieData;
    } else {
      // 2. Fallback to localStorage and migrate to cookie
      try {
        const raw1 = localStorage.getItem(STORAGE_BOOKMARKS_PRIMARY);
        const raw2 = localStorage.getItem(STORAGE_BOOKMARKS_SECONDARY);
        if (raw1) ids = ids.concat(JSON.parse(raw1));
        if (raw2) ids = ids.concat(JSON.parse(raw2));
      } catch (e) {}

      ids = Array.from(new Set(ids));

      // Seed initial defaults if completely empty
      if (ids.length === 0) {
        ids = [...DEFAULT_INITIAL_BOOKMARKS];
      }

      setCookie(COOKIE_BOOKMARKS, ids, 365);
    }

    // Mirror to localStorage for script compatibility
    try {
      localStorage.setItem(STORAGE_BOOKMARKS_PRIMARY, JSON.stringify(ids));
      localStorage.setItem(STORAGE_BOOKMARKS_SECONDARY, JSON.stringify(ids));
    } catch (e) {}

    return ids;
  }

  function saveBookmark(id) {
    if (!id) return;
    const current = getBookmarks();
    if (!current.includes(id)) {
      current.push(id);
      setCookie(COOKIE_BOOKMARKS, current, 365);
      try {
        localStorage.setItem(STORAGE_BOOKMARKS_PRIMARY, JSON.stringify(current));
        localStorage.setItem(STORAGE_BOOKMARKS_SECONDARY, JSON.stringify(current));
      } catch (e) {}

      // If user is signed in with Google, also sync to cloud copy
      const session = getSession();
      if (session && session.email) {
        try {
          localStorage.setItem('radiology_cloud_bookmarks_' + session.email, JSON.stringify(current));
        } catch (e) {}
      }

      dispatchBookmarkEvent();
    }
  }

  function removeBookmark(id) {
    if (!id) return;
    let current = getBookmarks();
    if (current.includes(id)) {
      current = current.filter(item => item !== id);
      setCookie(COOKIE_BOOKMARKS, current, 365);
      try {
        localStorage.setItem(STORAGE_BOOKMARKS_PRIMARY, JSON.stringify(current));
        localStorage.setItem(STORAGE_BOOKMARKS_SECONDARY, JSON.stringify(current));
      } catch (e) {}

      // If user is signed in with Google, also sync to cloud copy
      const session = getSession();
      if (session && session.email) {
        try {
          localStorage.setItem('radiology_cloud_bookmarks_' + session.email, JSON.stringify(current));
        } catch (e) {}
      }

      dispatchBookmarkEvent();
    }
  }

  function isBookmarked(id) {
    if (!id) return false;
    const list = getBookmarks();
    return list.includes(id);
  }

  function toggleBookmark(id) {
    if (isBookmarked(id)) {
      removeBookmark(id);
      return false;
    } else {
      saveBookmark(id);
      return true;
    }
  }

  function dispatchBookmarkEvent() {
    const list = getBookmarks();
    window.dispatchEvent(new CustomEvent('bookmarks-updated', { detail: { bookmarks: list, count: list.length } }));
  }

  /* ==========================================================================
     DOWNLOADS TRACKING (Browser Storage - Works Anonymously)
     ========================================================================== */

  const DEFAULT_INITIAL_DOWNLOADS = [
    {
      id: 'dl-physics-4th-ed',
      title: 'The Essential Physics of Medical Imaging (4th Edition Reference)',
      category: 'Diagnostic Physics',
      format: 'PDF',
      size: '48.2 MB',
      timestamp: Date.now() - 1000 * 60 * 60 * 24 * 2,
      url: '/books/'
    },
    {
      id: 'dl-stroke-aspects-card',
      title: 'Acute Ischemic Stroke ASPECTS Multi-Phase CTA Quick Triage Card',
      category: 'Neuroradiology',
      format: 'PDF',
      size: '4.2 MB',
      timestamp: Date.now() - 1000 * 60 * 60 * 24 * 5,
      url: '/post/index.html'
    },
    {
      id: 'dl-chest-ct-ild-atlas',
      title: 'High-Resolution Chest CT Interstitial Lung Disease Pattern Atlas',
      category: 'Thoracic Imaging',
      format: 'PDF',
      size: '32.6 MB',
      timestamp: Date.now() - 1000 * 60 * 60 * 24 * 9,
      url: '/books/'
    },
    {
      id: 'dl-msk-ultrasound-pocket',
      title: 'Dynamic Musculoskeletal Ultrasound & Rotator Cuff Pocket Companion',
      category: 'MSK Ultrasound',
      format: 'EPUB',
      size: '18.4 MB',
      timestamp: Date.now() - 1000 * 60 * 60 * 24 * 12,
      url: '/books/'
    }
  ];

  function getDownloads() {
    let list = [];
    try {
      const raw = localStorage.getItem(STORAGE_DOWNLOADS);
      if (raw) list = JSON.parse(raw);
    } catch (e) {}

    if (!Array.isArray(list) || list.length === 0) {
      list = [...DEFAULT_INITIAL_DOWNLOADS];
      try {
        localStorage.setItem(STORAGE_DOWNLOADS, JSON.stringify(list));
      } catch (e) {}
    }
    return list;
  }

  function saveDownload(item) {
    if (!item || !item.id) return;
    const current = getDownloads();
    const existingIndex = current.findIndex(d => d.id === item.id);
    if (existingIndex >= 0) {
      current[existingIndex] = { ...current[existingIndex], ...item, timestamp: Date.now() };
    } else {
      current.unshift({ ...item, timestamp: Date.now() });
    }
    try {
      localStorage.setItem(STORAGE_DOWNLOADS, JSON.stringify(current));
    } catch (e) {}

    // If user is signed in with Google, also sync to cloud copy
    const session = getSession();
    if (session && session.email) {
      try {
        localStorage.setItem('radiology_cloud_downloads_' + session.email, JSON.stringify(current));
      } catch (e) {}
    }

    window.dispatchEvent(new CustomEvent('downloads-updated', { detail: { downloads: current, count: current.length } }));
  }

  function removeDownload(id) {
    if (!id) return;
    let current = getDownloads();
    current = current.filter(d => d.id !== id);
    try {
      localStorage.setItem(STORAGE_DOWNLOADS, JSON.stringify(current));
    } catch (e) {}

    const session = getSession();
    if (session && session.email) {
      try {
        localStorage.setItem('radiology_cloud_downloads_' + session.email, JSON.stringify(current));
      } catch (e) {}
    }

    window.dispatchEvent(new CustomEvent('downloads-updated', { detail: { downloads: current, count: current.length } }));
  }

  /* ==========================================================================
     AUTHENTICATION & GOOGLE SYNCHRONIZATION
     ========================================================================== */

  /**
   * Retrieves active Google session, or null if user is anonymous.
   */
  function getSession() {
    let session = getCookie(COOKIE_SESSION);

    if (!session || typeof session !== 'object') {
      try {
        const raw = localStorage.getItem(STORAGE_SESSION);
        if (raw) session = JSON.parse(raw);
      } catch (e) {}
    }

    // Only recognize valid Google sessions (anonymous users have null session)
    if (session && typeof session === 'object' && (session.provider === 'google' || session.email)) {
      setCookie(COOKIE_SESSION, session, 365);
      try {
        localStorage.setItem(STORAGE_SESSION, JSON.stringify(session));
      } catch (e) {}
      return session;
    }

    return null;
  }

  /**
   * Google Sign-In & Synchronization
   * Merges:
   * - Bookmarks (no duplicates)
   * - Download history (no duplicates)
   * - Preserves current local theme as user's pending preference
   */
  function setGoogleAccount({ name, email, avatar, seed }) {
    const userEmail = email || 'mr.akshaypatel05@gmail.com';
    const userName = name || 'Akshay Patel';
    const userAvatar = avatar || (window.DiceBear && typeof window.DiceBear.getRandomAvatar === 'function' 
      ? window.DiceBear.getRandomAvatar(userEmail) 
      : '');

    // 1. Read existing local bookmarks
    const localBookmarks = getBookmarks();

    // 2. Read cloud bookmarks for this user if any
    let cloudBookmarks = [];
    try {
      const rawCloud = localStorage.getItem('radiology_cloud_bookmarks_' + userEmail);
      if (rawCloud) cloudBookmarks = JSON.parse(rawCloud);
    } catch (e) {}

    // Merge bookmarks (union, avoid duplicates)
    const mergedBookmarks = Array.from(new Set([...cloudBookmarks, ...localBookmarks]));
    setCookie(COOKIE_BOOKMARKS, mergedBookmarks, 365);
    try {
      localStorage.setItem(STORAGE_BOOKMARKS_PRIMARY, JSON.stringify(mergedBookmarks));
      localStorage.setItem(STORAGE_BOOKMARKS_SECONDARY, JSON.stringify(mergedBookmarks));
      localStorage.setItem('radiology_cloud_bookmarks_' + userEmail, JSON.stringify(mergedBookmarks));
    } catch (e) {}

    // 3. Read and merge download history
    const localDownloads = getDownloads();
    let cloudDownloads = [];
    try {
      const rawCloudDl = localStorage.getItem('radiology_cloud_downloads_' + userEmail);
      if (rawCloudDl) cloudDownloads = JSON.parse(rawCloudDl);
    } catch (e) {}

    const dlMap = new Map();
    cloudDownloads.forEach(d => { if (d && d.id) dlMap.set(d.id, d); });
    localDownloads.forEach(d => { if (d && d.id) dlMap.set(d.id, d); });
    const mergedDownloads = Array.from(dlMap.values());
    try {
      localStorage.setItem(STORAGE_DOWNLOADS, JSON.stringify(mergedDownloads));
      localStorage.setItem('radiology_cloud_downloads_' + userEmail, JSON.stringify(mergedDownloads));
    } catch (e) {}

    // 4. Preserve pending local theme preference
    let currentTheme = 'light';
    try {
      currentTheme = localStorage.getItem(STORAGE_THEME) || 
        ((window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) ? 'dark' : 'light');
      localStorage.setItem('radiology_cloud_theme_' + userEmail, currentTheme);
    } catch (e) {}

    const sessionData = {
      provider: 'google',
      isLocal: false,
      name: userName,
      email: userEmail,
      seed: seed || userEmail,
      avatar: userAvatar,
      isDicebear: true,
      canComment: true,
      joinedDate: 'September 25, 2026',
      timestamp: Date.now(),
      theme: currentTheme
    };

    setCookie(COOKIE_SESSION, sessionData, 365);
    try {
      localStorage.setItem(STORAGE_SESSION, JSON.stringify(sessionData));
    } catch (e) {}

    window.dispatchEvent(new CustomEvent('auth-state-changed', { detail: sessionData }));
    window.dispatchEvent(new CustomEvent('bookmarks-updated', { detail: { bookmarks: mergedBookmarks, count: mergedBookmarks.length } }));
    window.dispatchEvent(new CustomEvent('downloads-updated', { detail: { downloads: mergedDownloads, count: mergedDownloads.length } }));

    return sessionData;
  }

  /**
   * One-click Google Sign-In helper
   */
  function signInWithGoogle(options = {}) {
    return setGoogleAccount({
      name: options.name || 'Akshay Patel',
      email: options.email || 'mr.akshaypatel05@gmail.com',
      avatar: options.avatar,
      seed: options.seed
    });
  }

  /**
   * Sign out (ends active Google session)
   * Keeps current local theme intact
   * Preserves local bookmarks and download history in browser
   */
  function clearSession() {
    const session = getSession();
    if (session && session.email) {
      try {
        localStorage.setItem('radiology_cloud_bookmarks_' + session.email, JSON.stringify(getBookmarks()));
        localStorage.setItem('radiology_cloud_downloads_' + session.email, JSON.stringify(getDownloads()));
      } catch (e) {}
    }

    // Preserve the current local theme
    const currentTheme = localStorage.getItem(STORAGE_THEME);

    deleteCookie(COOKIE_SESSION);
    try {
      localStorage.removeItem(STORAGE_SESSION);
      if (currentTheme) {
        localStorage.setItem(STORAGE_THEME, currentTheme);
      }
    } catch (e) {}

    window.dispatchEvent(new CustomEvent('auth-state-changed', { detail: null }));
  }

  /**
   * Permissions: Only Google-authenticated users can comment.
   * Anonymous users cannot comment.
   */
  function canComment() {
    const session = getSession();
    return !!(session && session.provider === 'google' && session.email);
  }

  function isLoggedIn() {
    const session = getSession();
    return !!(session && session.provider === 'google' && session.email);
  }

  function isAnonymous() {
    return !isLoggedIn();
  }

  /**
   * Reset Account (Danger Action 1):
   * Clears saved application data (bookmarks, downloads, comments, streak)
   * while keeping profile intact.
   */
  function resetAccount() {
    // Clear bookmarks
    setCookie(COOKIE_BOOKMARKS, [], 365);
    try {
      localStorage.setItem(STORAGE_BOOKMARKS_PRIMARY, JSON.stringify([]));
      localStorage.setItem(STORAGE_BOOKMARKS_SECONDARY, JSON.stringify([]));
    } catch (e) {}

    // Clear downloads
    try {
      localStorage.setItem(STORAGE_DOWNLOADS, JSON.stringify([]));
    } catch (e) {}

    // Clear comments
    try {
      localStorage.setItem(STORAGE_COMMENTS, JSON.stringify([]));
    } catch (e) {}

    // Reset study streak
    try {
      localStorage.setItem(STORAGE_STREAK, '0');
    } catch (e) {}

    // If Google user, also reset their cloud data copy
    const session = getSession();
    if (session && session.email) {
      try {
        localStorage.setItem('radiology_cloud_bookmarks_' + session.email, JSON.stringify([]));
        localStorage.setItem('radiology_cloud_downloads_' + session.email, JSON.stringify([]));
      } catch (e) {}
    }

    dispatchBookmarkEvent();
    window.dispatchEvent(new CustomEvent('downloads-updated', { detail: { downloads: [], count: 0 } }));
    return true;
  }

  /**
   * Delete Google Account (Danger Action 2):
   * Permanently deletes Google-connected user data and ends Google session.
   * Reverts user to clean anonymous browser mode.
   */
  function deleteGoogleAccount() {
    const session = getSession();
    if (session && session.email) {
      try {
        localStorage.removeItem('radiology_cloud_bookmarks_' + session.email);
        localStorage.removeItem('radiology_cloud_downloads_' + session.email);
        localStorage.removeItem('radiology_cloud_theme_' + session.email);
      } catch (e) {}
    }

    // Keep current theme preference locally
    const currentTheme = localStorage.getItem(STORAGE_THEME);

    deleteCookie(COOKIE_SESSION);
    try {
      localStorage.removeItem(STORAGE_SESSION);
      if (currentTheme) {
        localStorage.setItem(STORAGE_THEME, currentTheme);
      }
    } catch (e) {}

    window.dispatchEvent(new CustomEvent('auth-state-changed', { detail: null }));
    return true;
  }

  // Toast Notification Helper (Delegates to unified Toast module)
  function showToast(message, type = 'info', options = {}) {
    if (window.Toast && typeof window.Toast.show === 'function') {
      return window.Toast.show(message, type, options);
    }
    if (window.showToast && window.showToast !== showToast) {
      return window.showToast(message, type, options);
    }
    // Fallback if toast module hasn't loaded yet
    console.log(`[Toast ${type}]:`, message);
  }

  // Backwards compatibility shim for any existing code calling old local methods
  function createLocalAccount() {
    return null;
  }
  function loginOrRestoreLocalAccount() {
    return { session: null, isExisting: false };
  }
  function findStoredAccount() {
    return null;
  }

  // Expose universal API
  window.RadiologyAuth = {
    // Cookie Helpers
    setCookie,
    getCookie,
    deleteCookie,

    // Bookmarks API (Local / Cookie)
    getBookmarks,
    saveBookmark,
    removeBookmark,
    isBookmarked,
    toggleBookmark,

    // Downloads API (Local)
    getDownloads,
    saveDownload,
    removeDownload,

    // Authentication & Google Sync API
    getSession,
    signInWithGoogle,
    setGoogleAccount,
    clearSession,
    resetAccount,
    deleteGoogleAccount,
    deleteAccount: deleteGoogleAccount, // alias for backwards compatibility
    isLoggedIn,
    isAnonymous,
    canComment,

    // Backwards compatibility
    createLocalAccount,
    loginOrRestoreLocalAccount,
    findStoredAccount,

    // UI Helper
    showToast
  };

  // Sync initial bookmarks on boot
  document.addEventListener('DOMContentLoaded', () => {
    getBookmarks();
    getDownloads();
  });

})();


/**
 * HEADER JS
 * Handles responsive interactions for the header component:
 * - Hamburger menu toggle and navigation drawer
 * - Minimal Search Modal popup and keyboard navigation
 * - Theme & Palette Modal / Mobile Bottom Sheet
 */

(function () {
  'use strict';

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      initHeader();
    });
  } else {
    initHeader();
  }

  function initHeader() {
    // DOM Elements - Navigation Drawer
    const hamburgerBtn = document.getElementById('hamburger-btn');
    const navDrawer = document.getElementById('nav-drawer');
    const navBackdrop = document.getElementById('nav-backdrop');
    const drawerCloseBtn = document.getElementById('drawer-close-btn');
    const navLinks = document.querySelectorAll('.nav-link');

    // DOM Elements - Search Modal
    const searchBtn = document.getElementById('search-btn');
    const searchModalOverlay = document.getElementById('search-modal-overlay');
    const searchModal = document.getElementById('search-modal');
    const searchForm = document.getElementById('search-form');
    const searchInput = document.getElementById('search-input');
    const searchClearBtn = document.getElementById('search-clear-btn');
    const searchCloseBtn = document.getElementById('search-close-btn');

    // DOM Elements - Theme & Palette Modal
    const modeBtn = document.getElementById('mode-btn');
    const themeModalOverlay = document.getElementById('theme-modal-overlay');
    const themeModal = document.getElementById('theme-modal');
    const themeCloseBtn = document.getElementById('theme-close-btn');
    const modeSelectButtons = document.querySelectorAll('.mode-select-btn');
    const paletteButtons = document.querySelectorAll('.palette-btn');

    // Check Blogger Layout mode switcher toggle setting
    const modeConfigEl = document.getElementById('mode-changer-config');
    if (modeConfigEl) {
      const modeVal = (modeConfigEl.getAttribute('data-content') || modeConfigEl.textContent || '').toLowerCase().trim();
      if (modeVal.includes('disable') || modeVal.includes('false') || modeVal.includes('off') || modeVal === '0') {
        const modeButtons = document.querySelectorAll('#mode-btn, .mode-btn, .header-btn.mode-btn');
        modeButtons.forEach(btn => btn.style.display = 'none');
      }
    }

    // Process Blogger Layout navigation sublinks (links starting with _ or -)
    const desktopList = document.querySelector('#header-desktop-nav .desktop-nav-list');
    if (desktopList) {
      const items = Array.from(desktopList.querySelectorAll(':scope > .desktop-nav-item'));
      let currentParent = null;
      let currentSubmenu = null;

      items.forEach(item => {
        const link = item.querySelector('a');
        if (!link) return;
        const text = link.textContent.trim();
        if (text.startsWith('_') || text.startsWith('-')) {
          const cleanText = text.replace(/^[_-\s]+/, '');
          link.textContent = cleanText;
          if (currentParent && currentSubmenu) {
            link.className = 'dropdown-link-item';
            const li = document.createElement('li');
            li.appendChild(link);
            currentSubmenu.appendChild(li);
            item.remove();
          }
        } else {
          currentParent = item;
          currentSubmenu = null;
          const next = item.nextElementSibling;
          const nextLink = next ? next.querySelector('a') : null;
          const nextText = nextLink ? nextLink.textContent.trim() : '';
          if (nextText.startsWith('_') || nextText.startsWith('-')) {
            currentParent.classList.add('has-dropdown');
            const origHref = link.getAttribute('href') || '#';
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'desktop-nav-btn';
            btn.setAttribute('aria-haspopup', 'true');
            btn.setAttribute('aria-expanded', 'false');
            btn.innerHTML = `<span class="desktop-nav-text">${text}</span><svg class="nav-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M19.9201 8.9502L13.4001 15.4702C12.6301 16.2402 11.3701 16.2402 10.6001 15.4702L4.08008 8.9502" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" /></svg>`;

            const panel = document.createElement('div');
            panel.className = 'desktop-dropdown-panel standard-dropdown-panel';
            panel.setAttribute('role', 'menu');

            const ul = document.createElement('ul');
            ul.className = 'dropdown-list';
            panel.appendChild(ul);

            currentParent.innerHTML = '';
            currentParent.appendChild(btn);
            currentParent.appendChild(panel);
            currentSubmenu = ul;
          }
        }
      });
    }

    // DOM Elements - Desktop Navigation
    const desktopNav = document.getElementById('header-desktop-nav');
    const allDesktopNavItems = document.querySelectorAll('.desktop-nav-item');
    const desktopDropdownItems = document.querySelectorAll('.desktop-nav-item.has-dropdown');

    /* ------------------------------------------------------------------------
       0. Desktop Navigation (Dropdowns & Mega Menu - Strictly Single Active)
       ------------------------------------------------------------------------ */
    let navHoverTimer = null;

    function closeAllDesktopDropdowns() {
      if (navHoverTimer) {
        clearTimeout(navHoverTimer);
        navHoverTimer = null;
      }
      desktopDropdownItems.forEach((item) => {
        item.classList.remove('is-open');
        const btn = item.querySelector('.desktop-nav-btn');
        if (btn) btn.setAttribute('aria-expanded', 'false');
      });
    }

    if (desktopNav) {
      // Direct link items (no dropdown) also close dropdowns immediately when hovered
      allDesktopNavItems.forEach((item) => {
        if (!item.classList.contains('has-dropdown')) {
          item.addEventListener('mouseenter', () => {
            closeAllDesktopDropdowns();
          });
        }
      });

      desktopDropdownItems.forEach((item) => {
        const btn = item.querySelector('.desktop-nav-btn');
        const panel = item.querySelector('.desktop-dropdown-panel');

        if (btn) {
          btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const wasOpen = item.classList.contains('is-open');
            closeAllDesktopDropdowns();
            if (!wasOpen) {
              item.classList.add('is-open');
              btn.setAttribute('aria-expanded', 'true');
            }
          });

          // Keyboard navigation: Space/Enter opens, ArrowDown moves into panel
          btn.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowDown') {
              e.preventDefault();
              closeAllDesktopDropdowns();
              item.classList.add('is-open');
              btn.setAttribute('aria-expanded', 'true');
              if (panel) {
                const firstLink = panel.querySelector('a');
                if (firstLink) firstLink.focus();
              }
            }
          });
        }

        // Hover handling with instant previous-menu clearing
        item.addEventListener('mouseenter', () => {
          if (navHoverTimer) {
            clearTimeout(navHoverTimer);
            navHoverTimer = null;
          }
          // Close all other dropdowns immediately
          desktopDropdownItems.forEach((other) => {
            if (other !== item) {
              other.classList.remove('is-open');
              const otherBtn = other.querySelector('.desktop-nav-btn');
              if (otherBtn) otherBtn.setAttribute('aria-expanded', 'false');
            }
          });
          item.classList.add('is-open');
          if (btn) btn.setAttribute('aria-expanded', 'true');
        });

        item.addEventListener('mouseleave', () => {
          if (navHoverTimer) clearTimeout(navHoverTimer);
          navHoverTimer = setTimeout(() => {
            item.classList.remove('is-open');
            if (btn) btn.setAttribute('aria-expanded', 'false');
          }, 140);
        });

        // Close when focus leaves the item completely
        item.addEventListener('focusout', (e) => {
          if (!item.contains(e.relatedTarget)) {
            item.classList.remove('is-open');
            if (btn) btn.setAttribute('aria-expanded', 'false');
          }
        });

        // Clicking links inside panel closes the dropdown smoothly
        if (panel) {
          const links = panel.querySelectorAll('a');
          links.forEach((link) => {
            link.addEventListener('click', () => {
              closeAllDesktopDropdowns();
            });
          });
        }
      });

      // Global click outside to close desktop dropdowns
      document.addEventListener('click', (e) => {
        if (desktopNav && !desktopNav.contains(e.target)) {
          closeAllDesktopDropdowns();
        }
      });
    }

    /* ------------------------------------------------------------------------
       1. Hamburger Menu & Navigation Drawer
       ------------------------------------------------------------------------ */
    function openDrawer() {
      if (!navDrawer || !hamburgerBtn) return;
      hamburgerBtn.setAttribute('aria-expanded', 'true');
      navDrawer.classList.add('is-open');
      if (navBackdrop) navBackdrop.classList.add('is-active');
      document.body.classList.add('nav-drawer-open');
    }

    function closeDrawer() {
      if (!navDrawer || !hamburgerBtn) return;
      hamburgerBtn.setAttribute('aria-expanded', 'false');
      navDrawer.classList.remove('is-open');
      if (navBackdrop) navBackdrop.classList.remove('is-active');
      document.body.classList.remove('nav-drawer-open');
    }

    function toggleDrawer() {
      const isExpanded = hamburgerBtn.getAttribute('aria-expanded') === 'true';
      if (isExpanded) {
        closeDrawer();
      } else {
        openDrawer();
      }
    }

    if (hamburgerBtn) {
      hamburgerBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        toggleDrawer();
      });
    }

    if (drawerCloseBtn) {
      drawerCloseBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        closeDrawer();
      });
    }

    if (navBackdrop) {
      navBackdrop.addEventListener('click', () => {
        closeDrawer();
      });
    }

    /* ------------------------------------------------------------------------
       Expandable Tree-View Navigation Logic
       ------------------------------------------------------------------------ */
    const treeRoot = document.getElementById('tree-root');

    /**
     * Toggles a parent tree item expanded/collapsed state
     */
    function toggleParentItem(parentItem, forceState) {
      if (!parentItem) return;
      const row = parentItem.querySelector('.tree-parent-row');
      const chevronBtn = parentItem.querySelector('.tree-chevron-btn');
      const wrapper = parentItem.querySelector('.tree-children-wrapper');

      const isCurrentlyExpanded = parentItem.classList.contains('is-expanded');
      const shouldExpand = typeof forceState === 'boolean' ? forceState : !isCurrentlyExpanded;

      if (shouldExpand) {
        parentItem.classList.add('is-expanded');
        if (wrapper) wrapper.classList.add('is-expanded');
        if (row) row.setAttribute('aria-expanded', 'true');
        if (chevronBtn) chevronBtn.setAttribute('aria-expanded', 'true');
      } else {
        parentItem.classList.remove('is-expanded');
        if (wrapper) wrapper.classList.remove('is-expanded');
        if (row) row.setAttribute('aria-expanded', 'false');
        if (chevronBtn) chevronBtn.setAttribute('aria-expanded', 'false');
      }
    }

    /**
     * Selects an active tree item
     */
    function selectTreeItem(itemEl) {
      if (!itemEl) return;
      const allRows = document.querySelectorAll('.tree-row');
      allRows.forEach((r) => {
        r.classList.remove('is-active');
        r.setAttribute('aria-selected', 'false');
      });

      const activeRow = itemEl.querySelector('.tree-row');
      if (activeRow) {
        activeRow.classList.add('is-active');
        activeRow.setAttribute('aria-selected', 'true');
      }

      // Close drawer on mobile screens (< 1024px) for a responsive workflow
      if (window.innerWidth < 1024) {
        closeDrawer();
      }
    }

    // Attach click and keyboard listeners to all tree parents
    const treeParents = document.querySelectorAll('.tree-parent');
    treeParents.forEach((parent) => {
      const row = parent.querySelector('.tree-parent-row');
      const chevronBtn = parent.querySelector('.tree-chevron-btn');

      if (chevronBtn) {
        chevronBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          toggleParentItem(parent);
        });
      }

      if (row) {
        row.addEventListener('click', (e) => {
          toggleParentItem(parent);
        });

        // Accessible keyboard navigation for tree parent items
        row.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            toggleParentItem(parent);
          } else if (e.key === 'ArrowRight') {
            e.preventDefault();
            toggleParentItem(parent, true);
          } else if (e.key === 'ArrowLeft') {
            e.preventDefault();
            toggleParentItem(parent, false);
          }
        });
      }
    });

    // Attach click and keyboard listeners to all tree leaves
    const treeLeaves = document.querySelectorAll('.tree-leaf');
    treeLeaves.forEach((leaf) => {
      const leafLink = leaf.querySelector('.tree-leaf-link');
      if (leafLink) {
        leafLink.addEventListener('click', (e) => {
          const href = leafLink.getAttribute('href');
          selectTreeItem(leaf);
          if (href && href.startsWith('#')) {
            const targetEl = document.querySelector(href);
            if (targetEl) {
              e.preventDefault();
              targetEl.scrollIntoView({ behavior: 'smooth' });
              history.pushState(null, '', href);
            }
          }
        });

        leafLink.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            const href = leafLink.getAttribute('href');
            selectTreeItem(leaf);
            if (href && href.startsWith('#')) {
              const targetEl = document.querySelector(href);
              if (targetEl) {
                e.preventDefault();
                targetEl.scrollIntoView({ behavior: 'smooth' });
                history.pushState(null, '', href);
              }
            } else if (href) {
              window.location.href = href;
            }
          }
        });
      }
    });

    /* ------------------------------------------------------------------------
       2. Clean Minimal Search Modal Interactions
       ------------------------------------------------------------------------ */
    function openSearchModal() {
      if (!searchModalOverlay || !searchBtn) return;
      // Close theme modal and desktop dropdowns if open
      closeThemeModal();
      closeAllDesktopDropdowns();
      searchModalOverlay.classList.add('is-active');
      searchBtn.setAttribute('aria-expanded', 'true');
      document.body.classList.add('modal-open');

      if (searchInput) {
        setTimeout(() => {
          searchInput.focus();
        }, 60);
      }
    }

    function closeSearchModal() {
      if (!searchModalOverlay || !searchBtn) return;
      if (searchModal) {
        searchModal.style.transform = '';
        searchModal.style.transition = '';
      }
      searchModalOverlay.classList.remove('is-active');
      searchBtn.setAttribute('aria-expanded', 'false');
      document.body.classList.remove('modal-open');
      if (searchInput) {
        searchInput.blur();
      }
    }

    if (searchBtn) {
      searchBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openSearchModal();
      });
    }

    if (searchCloseBtn) {
      searchCloseBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        closeSearchModal();
      });
    }

    if (searchModalOverlay) {
      searchModalOverlay.addEventListener('click', (e) => {
        if (e.target === searchModalOverlay) {
          closeSearchModal();
        }
      });
    }

    if (searchModal) {
      searchModal.addEventListener('click', (e) => {
        e.stopPropagation();
      });
    }

    if (searchInput) {
      searchInput.addEventListener('input', () => {
        if (searchClearBtn) {
          if (searchInput.value.trim().length > 0) {
            searchClearBtn.classList.add('is-visible');
          } else {
            searchClearBtn.classList.remove('is-visible');
          }
        }
      });
    }

    if (searchClearBtn && searchInput) {
      searchClearBtn.addEventListener('click', (e) => {
        e.preventDefault();
        searchInput.value = '';
        searchClearBtn.classList.remove('is-visible');
        searchInput.focus();
      });
    }

    if (searchForm) {
      searchForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const query = searchInput ? searchInput.value.trim() : '';
        if (query) {
          if (typeof window.radiologySearch === 'function') {
            window.radiologySearch(query, `Query: "${query}"`);
          }
          closeSearchModal();
        }
      });
    }

    /* Mobile Search Sheet Touch Swipe-Down Dismiss with rAF throttling for 60fps */
    if (searchModal) {
      let touchStartY = 0;
      let touchCurrentY = 0;
      let isDraggingSheet = false;
      let searchRafId = null;

      searchModal.addEventListener('touchstart', (e) => {
        if (window.innerWidth >= 640) return;
        if (e.target === searchInput) return;
        touchStartY = e.touches[0].clientY;
        touchCurrentY = touchStartY;
        isDraggingSheet = true;
      }, { passive: true });

      searchModal.addEventListener('touchmove', (e) => {
        if (!isDraggingSheet || window.innerWidth >= 640) return;
        touchCurrentY = e.touches[0].clientY;
        const deltaY = touchCurrentY - touchStartY;
        if (deltaY > 0) {
          if (!searchRafId) {
            searchRafId = requestAnimationFrame(() => {
              searchModal.style.transition = 'none';
              searchModal.style.transform = `translate3d(0, ${deltaY}px, 0)`;
              searchRafId = null;
            });
          }
        }
      }, { passive: true });

      searchModal.addEventListener('touchend', () => {
        if (!isDraggingSheet || window.innerWidth >= 640) return;
        isDraggingSheet = false;
        if (searchRafId) {
          cancelAnimationFrame(searchRafId);
          searchRafId = null;
        }
        const deltaY = touchCurrentY - touchStartY;
        searchModal.style.transition = '';
        if (deltaY > 60) {
          closeSearchModal();
        } else {
          searchModal.style.transform = '';
        }
      });
    }

    /* ------------------------------------------------------------------------
       3. Theme & Palette Modal / Mobile Bottom Sheet Interactions
       ------------------------------------------------------------------------ */
    function openThemeModal() {
      if (!themeModalOverlay || !modeBtn) return;
      // Close search modal and desktop dropdowns if open
      closeSearchModal();
      closeAllDesktopDropdowns();
      themeModalOverlay.classList.add('is-active');
      modeBtn.setAttribute('aria-expanded', 'true');
      document.body.classList.add('modal-open');
    }

    function closeThemeModal() {
      if (!themeModalOverlay || !modeBtn) return;
      if (themeModal) {
        themeModal.style.transform = '';
        themeModal.style.transition = '';
      }
      themeModalOverlay.classList.remove('is-active');
      modeBtn.setAttribute('aria-expanded', 'false');
      document.body.classList.remove('modal-open');
    }

    if (modeBtn) {
      modeBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (themeModalOverlay && themeModalOverlay.classList.contains('is-active')) {
          closeThemeModal();
        } else {
          openThemeModal();
        }
      });
    }

    if (themeCloseBtn) {
      themeCloseBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        closeThemeModal();
      });
    }

    // Close when clicking outside theme modal card
    if (themeModalOverlay) {
      themeModalOverlay.addEventListener('click', (e) => {
        if (e.target === themeModalOverlay) {
          closeThemeModal();
        }
      });
    }

    if (themeModal) {
      themeModal.addEventListener('click', (e) => {
        e.stopPropagation();
      });
    }

    // Mode Buttons inside Modal (Light / Dark)
    modeSelectButtons.forEach((btn) => {
      btn.addEventListener('click', () => {
        const modeVal = btn.getAttribute('data-mode-val');
        if (window.GlobalTheme && typeof window.GlobalTheme.setTheme === 'function') {
          window.GlobalTheme.setTheme(modeVal);
        }
      });
    });

    // Palette Buttons inside Modal (10 Subtle Material Tones)
    paletteButtons.forEach((btn) => {
      btn.addEventListener('click', () => {
        const paletteVal = btn.getAttribute('data-palette-val');
        if (window.GlobalTheme && typeof window.GlobalTheme.setPalette === 'function') {
          window.GlobalTheme.setPalette(paletteVal);
        }
      });
    });

    /* Mobile Theme Sheet Touch Swipe-Down Dismiss with rAF throttling */
    if (themeModal) {
      let touchStartY = 0;
      let touchCurrentY = 0;
      let isDraggingSheet = false;
      let themeRafId = null;

      themeModal.addEventListener('touchstart', (e) => {
        if (window.innerWidth >= 640) return;
        touchStartY = e.touches[0].clientY;
        touchCurrentY = touchStartY;
        isDraggingSheet = true;
      }, { passive: true });

      themeModal.addEventListener('touchmove', (e) => {
        if (!isDraggingSheet || window.innerWidth >= 640) return;
        touchCurrentY = e.touches[0].clientY;
        const deltaY = touchCurrentY - touchStartY;
        if (deltaY > 0) {
          if (!themeRafId) {
            themeRafId = requestAnimationFrame(() => {
              themeModal.style.transition = 'none';
              themeModal.style.transform = `translate3d(0, ${deltaY}px, 0)`;
              themeRafId = null;
            });
          }
        }
      }, { passive: true });

      themeModal.addEventListener('touchend', () => {
        if (!isDraggingSheet || window.innerWidth >= 640) return;
        isDraggingSheet = false;
        if (themeRafId) {
          cancelAnimationFrame(themeRafId);
          themeRafId = null;
        }
        const deltaY = touchCurrentY - touchStartY;
        themeModal.style.transition = '';
        if (deltaY > 60) {
          closeThemeModal();
        } else {
          themeModal.style.transform = '';
        }
      });
    }

    /* ------------------------------------------------------------------------
       4. Keyboard Shortcuts (Escape to close Modal & Drawer & Dropdowns)
       ------------------------------------------------------------------------ */
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeAllDesktopDropdowns();
        if (themeModalOverlay && themeModalOverlay.classList.contains('is-active')) {
          closeThemeModal();
          return;
        }
        if (searchModalOverlay && searchModalOverlay.classList.contains('is-active')) {
          closeSearchModal();
          return;
        }
        if (navDrawer && navDrawer.classList.contains('is-open')) {
          closeDrawer();
        }
      }

      // Quick slash / shortcut to open search if not typing inside an input
      if (e.key === '/' && document.activeElement !== searchInput) {
        if (searchModalOverlay && !searchModalOverlay.classList.contains('is-active')) {
          e.preventDefault();
          openSearchModal();
        }
      }
    });

    // Throttled resize listener
    let resizeTimer = null;
    window.addEventListener('resize', () => {
      if (resizeTimer) return;
      resizeTimer = requestAnimationFrame(() => {
        if (window.innerWidth >= 1024) {
          closeDrawer();
        }
        resizeTimer = null;
      });
    });

    /* ------------------------------------------------------------------------
       5. User Header Icon: Entry point to Workspace (Anonymous or Google)
       ------------------------------------------------------------------------ */
    function syncHeaderUserAuth() {
      const userBtn = document.getElementById('header-user-btn');
      const userIcon = document.getElementById('user-header-icon');
      const userAvatar = document.getElementById('user-header-avatar');
      if (!userBtn) return;

      const STORAGE_KEY = 'my_radiology_user_session';
      let session = null;
      if (window.RadiologyAuth && typeof window.RadiologyAuth.getSession === 'function') {
        session = window.RadiologyAuth.getSession();
      } else {
        try {
          const raw = localStorage.getItem(STORAGE_KEY);
          if (raw) session = JSON.parse(raw);
        } catch (e) {}
      }

      // Calculate path relative to subfolder
      const pathname = window.location.pathname || '';
      const isSubfolder = pathname.includes('/books') || 
                          pathname.includes('/login') || 
                          pathname.includes('/post') || 
                          pathname.includes('/account') ||
                          pathname.includes('/workspace');

      const workspaceHref = isSubfolder ? '../account/index.html' : 'account/index.html';

      // Clicking the user icon ALWAYS opens/navigates to Workspace
      userBtn.href = workspaceHref;

      if (session && session.email && (session.provider === 'google' || !session.isLocal)) {
        // User is signed in with Google -> show Google avatar
        userBtn.classList.add('has-avatar');
        userBtn.setAttribute('aria-label', `Workspace: ${session.name || session.email}`);
        userBtn.setAttribute('title', `Workspace: ${session.name || session.email}`);

        if (userIcon) userIcon.classList.add('is-hidden');

        if (userAvatar) {
          let avatarUrl = session.avatar;
          const userSeed = session.email || session.name || 'radiology-user';
          if (!avatarUrl && window.DiceBear && typeof window.DiceBear.getRandomAvatar === 'function') {
            avatarUrl = window.DiceBear.getRandomAvatar(userSeed);
            session.avatar = avatarUrl;
            try {
              localStorage.setItem(STORAGE_KEY, JSON.stringify(session));
            } catch (e) {}
          }
          if (avatarUrl) {
            userAvatar.src = avatarUrl;
            userAvatar.alt = session.name || 'User profile';
            userAvatar.classList.remove('is-hidden');
          } else {
            if (userIcon) userIcon.classList.remove('is-hidden');
            userAvatar.classList.add('is-hidden');
            userBtn.classList.remove('has-avatar');
          }
        }
      } else {
        // Anonymous user -> show SVG icon & still navigate directly to Workspace
        userBtn.classList.remove('has-avatar');
        userBtn.setAttribute('aria-label', 'Workspace');
        userBtn.setAttribute('title', 'Workspace');

        if (userIcon) userIcon.classList.remove('is-hidden');
        if (userAvatar) userAvatar.classList.add('is-hidden');
      }
    }

    // Run initial auth state sync
    syncHeaderUserAuth();

    // Listen for custom and cross-tab storage events
    window.addEventListener('auth-state-changed', () => {
      syncHeaderUserAuth();
    });
    window.addEventListener('storage', (e) => {
      if (e.key === 'my_radiology_user_session') {
        syncHeaderUserAuth();
      }
    });

    // Remove preload class after page load to allow smooth user interactions with zero startup lag
    window.addEventListener('load', () => {
      requestAnimationFrame(() => {
        document.documentElement.classList.remove('preload');
      });
    });
  }
})();


/**
 * CAROUSEL JS
 * Handles carousel dynamic slide rendering from MRG_CONFIG,
 * transitions, dot indicators, autoplay with pause on hover/focus,
 * touch gestures, and keyboard navigation.
 */

(function () {
  'use strict';

  document.addEventListener('DOMContentLoaded', () => {
    initCarousel();
    initTopicsShowMore();
    initPinnedPostActions();
  });

  // Re-render when config changes from Admin
  window.addEventListener('mrgconfigchange', () => {
    initCarousel(true);
  });
  window.addEventListener('carouselconfigchange', () => {
    initCarousel(true);
  });

  function initPinnedPostActions() {
    const bookmarkBtn = document.getElementById('pinned-bookmark-btn');
    const bookmarkText = document.getElementById('pinned-bookmark-text');
    const shareBtn = document.getElementById('pinned-share-btn');
    const shareText = document.getElementById('pinned-share-text');

    const PINNED_SVG_PLUS = `<g clip-path="url(#clip0_save_btn)">
        <path d="M14.5 10.6504H9.5" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
        <path d="M12 8.21094V13.2109" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
        <path d="M16.8199 2H7.17995C5.04995 2 3.31995 3.74 3.31995 5.86V19.95C3.31995 21.75 4.60995 22.51 6.18995 21.64L11.0699 18.93C11.5899 18.64 12.4299 18.64 12.9399 18.93L17.8199 21.64C19.3999 22.52 20.6899 21.76 20.6899 19.95V5.86C20.6799 3.74 18.9499 2 16.8199 2Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
      </g>
      <defs>
        <clipPath id="clip0_save_btn">
          <rect width="24" height="24" fill="white"/>
        </clipPath>
      </defs>`;
    const PINNED_SVG_MINUS = `<g clip-path="url(#clip0_save_btn)">
        <path d="M14.5 10.6504H9.5" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
        <path d="M12 8.21094V13.2109" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
        <path d="M16.8199 2H7.17995C5.04995 2 3.31995 3.74 3.31995 5.86V19.95C3.31995 21.75 4.60995 22.51 6.18995 21.64L11.0699 18.93C11.5899 18.64 12.4299 18.64 12.9399 18.93L17.8199 21.64C19.3999 22.52 20.6899 21.76 20.6899 19.95V5.86C20.6799 3.74 18.9499 2 16.8199 2Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
      </g>
      <defs>
        <clipPath id="clip0_save_btn">
          <rect width="24" height="24" fill="white"/>
        </clipPath>
      </defs>`;

    if (bookmarkBtn) {
      bookmarkBtn.addEventListener('click', () => {
        const isSaved = bookmarkBtn.classList.toggle('is-active');
        bookmarkBtn.setAttribute('aria-pressed', String(isSaved));
        const iconSvg = bookmarkBtn.querySelector('svg');
        if (iconSvg) {
          iconSvg.innerHTML = isSaved ? PINNED_SVG_MINUS : PINNED_SVG_PLUS;
        }
        if (bookmarkText) {
          bookmarkText.textContent = isSaved ? 'Saved' : 'Save';
        }
      });
    }

    if (shareBtn) {
      shareBtn.addEventListener('click', () => {
        if (typeof window.openShareModal === 'function') {
          const pinnedTitleEl = document.getElementById('pinned-title-link');
          const pinnedDescEl = document.getElementById('pinned-post-desc');
          const title = pinnedTitleEl ? pinnedTitleEl.textContent.trim() : 'Acute Ischemic Stroke: Multiphase CTA Collateral Atlas & ASPECTS Triage Protocol';
          const description = pinnedDescEl ? pinnedDescEl.textContent.trim() : 'Comprehensive acute neurovascular imaging pathway covering rapid collateral grading, early ischemic core mapping, and standardized acute triage.';
          const url = window.location.origin + '/post/?id=neuroradiology-stroke-cta';
          const image = 'https://images.unsplash.com/photo-1516549655169-df83a0774514?auto=format&fit=crop&w=600&q=80';
          window.openShareModal({ title, description, url, image });
        }
      });
    }
  }

  function initTopicsShowMore() {
    const toggleBtn = document.getElementById('topics-toggle-btn');
    const wrapper = document.getElementById('topics-expandable-wrapper');
    const toggleText = document.getElementById('topics-toggle-text');
    const hiddenItems = document.querySelectorAll('.topic-item.is-hidden-initially');

    if (!toggleBtn || !wrapper) return;

    const moreText = toggleBtn.getAttribute('data-more-text') || 'Show More Topics';
    const lessText = toggleBtn.getAttribute('data-less-text') || 'Show Less Topics';

    toggleBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();

      const isExpanded = toggleBtn.getAttribute('aria-expanded') === 'true';
      const willExpand = !isExpanded;

      const lockedScrollY = window.scrollY || window.pageYOffset || document.documentElement.scrollTop;

      toggleBtn.setAttribute('aria-expanded', String(willExpand));
      wrapper.setAttribute('aria-hidden', String(!willExpand));

      if (willExpand) {
        wrapper.classList.add('is-expanded');
        if (toggleText) toggleText.textContent = lessText;
        hiddenItems.forEach((item) => item.removeAttribute('tabindex'));
      } else {
        wrapper.classList.remove('is-expanded');
        if (toggleText) toggleText.textContent = moreText;
        hiddenItems.forEach((item) => item.setAttribute('tabindex', '-1'));
      }

      if (e.detail > 0) toggleBtn.blur();

      const startTime = performance.now();
      const lockDuration = 420;

      function lockScroll(now) {
        const currentY = window.scrollY || window.pageYOffset || document.documentElement.scrollTop;
        if (Math.abs(currentY - lockedScrollY) > 0.5) {
          window.scrollTo({ top: lockedScrollY, behavior: 'instant' });
        }
        if (now - startTime < lockDuration) {
          requestAnimationFrame(lockScroll);
        }
      }

      requestAnimationFrame(lockScroll);
    });
  }

  function initCarousel(forceReRender = false) {
    const container = document.getElementById('featured-carousel');
    if (!container) return;

    const track = container.querySelector('.carousel-track');
    const dotsContainer = container.querySelector('.carousel-dots');
    if (!track) return;

    // Check dynamic slides from Blogger Layout widget or MRG_CONFIG
    let bloggerSlides = null;
    const bloggerSource = document.getElementById('blogger-carousel-source');
    if (bloggerSource) {
      const items = bloggerSource.querySelectorAll('.carousel-slide-item');
      if (items.length > 0) {
        bloggerSlides = Array.from(items).map(item => ({
          image: item.getAttribute('data-image') || '',
          tag: item.getAttribute('data-tag') || 'Clinical Reference',
          title: item.getAttribute('data-title') || '',
          desc: item.getAttribute('data-desc') || '',
          link: item.getAttribute('data-url') || item.getAttribute('data-link') || '#'
        }));
      }
    }
    const slidesData = bloggerSlides || window.MRG_CONFIG?.carousel;
    if (forceReRender || existingSlides.length === 0) {
      if (Array.isArray(slidesData) && slidesData.length > 0) {
        // Re-render track with dynamic slides maintaining full rich markup
        let slidesHtml = '';
        slidesData.forEach((s, idx) => {
          const isActive = idx === 0;
          const rawTags = Array.isArray(s.tags) ? s.tags : (s.tag ? [s.tag] : ['Clinical Reference']);
          const tagsHtml = rawTags.map(tag => `
            <span class="slide-tag">
              <svg class="slide-tag-hash-icon" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                <path d="M10 3L8 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                <path d="M16 3L14 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                <path d="M3.5 9H21.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                <path d="M2.5 15H20.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
              </svg>${tag}
            </span>
          `).join('');

          slidesHtml += `
            <article class="carousel-slide ${isActive ? 'is-active' : ''}" role="group" aria-roledescription="slide" aria-label="${idx + 1} of ${slidesData.length}" aria-hidden="${!isActive}">
              <img
                src="${s.image || 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=1600&auto=format&fit=crop&q=80'}"
                alt="${s.title || 'Slide'}"
                class="carousel-slide-img"
                loading="${idx === 0 ? 'eager' : 'lazy'}"
                referrerpolicy="no-referrer"
                onerror="this.src='https://images.unsplash.com/photo-1516549655169-df83a0774514?w=1600&auto=format&fit=crop&q=80'"
              />
              <div class="carousel-overlay">
                <div class="slide-tags">
                  ${tagsHtml}
                </div>
                <h2 class="slide-title">
                  ${s.link ? `<a href="${s.link}" style="color: inherit; text-decoration: none;">${s.title || ''}</a>` : (s.title || '')}
                </h2>
                ${s.desc ? `<p class="slide-desc">${s.desc}</p>` : ''}
              </div>
            </article>
          `;
        });
        track.innerHTML = slidesHtml;

        // Re-render dots
        if (dotsContainer) {
          let dotsHtml = '';
          slidesData.forEach((s, idx) => {
            const isActive = idx === 0;
            dotsHtml += `
              <button
                type="button"
                class="carousel-dot ${isActive ? 'is-active' : ''}"
                role="tab"
                aria-selected="${isActive ? 'true' : 'false'}"
                aria-label="Slide ${idx + 1} of ${slidesData.length}: ${s.title || ''}"
                data-slide-index="${idx}"
                tabindex="${isActive ? '0' : '-1'}"
              ></button>
            `;
          });
          dotsContainer.innerHTML = dotsHtml;
        }
      }
    }

    const slides = Array.from(container.querySelectorAll('.carousel-slide'));
    const dots = Array.from(container.querySelectorAll('.carousel-dot'));
    if (slides.length === 0) return;

    let currentIndex = 0;
    const totalSlides = slides.length;
    let autoplayTimer = null;
    const AUTOPLAY_INTERVAL = 5500;

    function goToSlide(index) {
      if (index < 0) {
        currentIndex = totalSlides - 1;
      } else if (index >= totalSlides) {
        currentIndex = 0;
      } else {
        currentIndex = index;
      }

      slides.forEach((slide, idx) => {
        const isActive = idx === currentIndex;
        slide.classList.toggle('is-active', isActive);
        slide.setAttribute('aria-hidden', !isActive);
      });

      dots.forEach((dot, idx) => {
        const isActive = idx === currentIndex;
        dot.classList.toggle('is-active', isActive);
        dot.setAttribute('aria-selected', isActive ? 'true' : 'false');
        dot.setAttribute('tabindex', isActive ? '0' : '-1');
      });
    }

    function nextSlide() {
      goToSlide(currentIndex + 1);
    }

    function prevSlide() {
      goToSlide(currentIndex - 1);
    }

    dots.forEach((dot) => {
      dot.addEventListener('click', () => {
        const targetIndex = parseInt(dot.getAttribute('data-slide-index'), 10);
        if (!isNaN(targetIndex)) {
          goToSlide(targetIndex);
          restartAutoplay();
        }
      });
    });

    function startAutoplay() {
      stopAutoplay();
      autoplayTimer = setInterval(() => {
        nextSlide();
      }, AUTOPLAY_INTERVAL);
    }

    function stopAutoplay() {
      if (autoplayTimer) {
        clearInterval(autoplayTimer);
        autoplayTimer = null;
      }
    }

    function restartAutoplay() {
      startAutoplay();
    }

    container.addEventListener('mouseenter', stopAutoplay);
    container.addEventListener('mouseleave', startAutoplay);
    container.addEventListener('focusin', stopAutoplay);
    container.addEventListener('focusout', startAutoplay);

    // Keyboard navigation
    container.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        prevSlide();
        restartAutoplay();
      } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        nextSlide();
        restartAutoplay();
      }
    });

    // Touch gesture navigation
    let touchStartX = 0;
    let touchEndX = 0;
    const SWIPE_THRESHOLD = 50;

    container.addEventListener('touchstart', (e) => {
      touchStartX = e.changedTouches[0].screenX;
      stopAutoplay();
    }, { passive: true });

    container.addEventListener('touchend', (e) => {
      touchEndX = e.changedTouches[0].screenX;
      handleSwipe();
      startAutoplay();
    }, { passive: true });

    function handleSwipe() {
      const diff = touchEndX - touchStartX;
      if (Math.abs(diff) >= SWIPE_THRESHOLD) {
        if (diff < 0) {
          nextSlide();
        } else {
          prevSlide();
        }
      }
    }

    startAutoplay();
  }
})();


/**
 * posts-data.js
 * Central Data Source for Clinical Radiology Posts
 * 
 * Schema:
