  let currentShareData = {
    title: '',
    description: '',
    image: '',
    url: ''
  };

  function ensureModalInDOM() {
    let overlay = document.getElementById('share-modal-overlay');
    if (!overlay) {
      const div = document.createElement('div');
      div.innerHTML = SHARE_MODAL_HTML.trim();
      overlay = div.firstElementChild;
      document.body.appendChild(overlay);
      initShareModalEvents(overlay);
    } else if (!overlay.hasAttribute('data-events-bound')) {
      initShareModalEvents(overlay);
    }
    return overlay;
  }

  function initShareModalEvents(overlay) {
    if (overlay.hasAttribute('data-events-bound')) return;
    overlay.setAttribute('data-events-bound', 'true');

    const closeBtn = document.getElementById('share-close-btn');
    const modal = document.getElementById('share-modal');
    const sheetHandle = document.getElementById('share-sheet-handle');
    const copyBtn = document.getElementById('share-copy-btn');
    const urlInput = document.getElementById('share-url-input');

    if (closeBtn) {
      closeBtn.addEventListener('click', closeShareModal);
    }

    // Dismiss on backdrop click
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) {
        closeShareModal();
      }
    });

    // Dismiss on ESC key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && overlay.classList.contains('is-active')) {
        closeShareModal();
      }
    });

    // Touch swipe down on mobile handle
    if (sheetHandle && modal) {
      let touchStartY = 0;
      let touchCurrentY = 0;

      sheetHandle.addEventListener('touchstart', (e) => {
        touchStartY = e.touches[0].clientY;
      }, { passive: true });

      sheetHandle.addEventListener('touchmove', (e) => {
        touchCurrentY = e.touches[0].clientY;
        const diff = touchCurrentY - touchStartY;
        if (diff > 0) {
          modal.style.transform = `translate3d(0, ${diff}px, 0)`;
        }
      }, { passive: true });

      sheetHandle.addEventListener('touchend', () => {
        const diff = touchCurrentY - touchStartY;
        modal.style.transform = '';
        if (diff > 75) {
          closeShareModal();
        }
        touchStartY = 0;
        touchCurrentY = 0;
      });
    }

    // Platform Pills Click Handlers
    const pillsRow = document.getElementById('share-pills-row');
    if (pillsRow) {
      pillsRow.addEventListener('click', (e) => {
        const btn = e.target.closest('.share-platform-pill');
        if (!btn) return;
        const platform = btn.getAttribute('data-platform');
        handlePlatformShare(platform);
      });
    }

    // Copy URL Button (Big icon-only button)
    if (copyBtn && urlInput) {
      copyBtn.addEventListener('click', async () => {
        const urlToCopy = urlInput.value || window.location.href;
        let copied = false;
        try {
          await navigator.clipboard.writeText(urlToCopy);
          copied = true;
        } catch (err) {
          urlInput.select();
          try {
            document.execCommand('copy');
            copied = true;
          } catch (e) {}
        }

        if (copied) {
          const iconSpan = document.getElementById('share-copy-btn-icon');
          copyBtn.classList.add('is-copied');
          if (iconSpan) iconSpan.innerHTML = CHECK_SVG;

          if (window.RadiologyAuth && typeof window.RadiologyAuth.showToast === 'function') {
            window.RadiologyAuth.showToast('Link copied to clipboard', 'copy');
          }

          setTimeout(() => {
            copyBtn.classList.remove('is-copied');
            if (iconSpan) iconSpan.innerHTML = COPY_SVG;
          }, 2200);
        }
      });
    }
  }

  function handlePlatformShare(platform) {
    const { title, description, url } = currentShareData;
    const shareText = title ? `${title} - ${description || ''}`.trim() : 'My Radiology Guide protocol';
    let shareUrl = '';

    switch (platform) {
      case 'facebook':
        shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`;
        break;
      case 'whatsapp':
        shareUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(title + '\n' + url)}`;
        break;
      case 'x':
        shareUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(title)}&url=${encodeURIComponent(url)}`;
        break;
      case 'telegram':
        shareUrl = `https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(title)}`;
        break;
      case 'pinterest':
        shareUrl = `https://pinterest.com/pin/create/button/?url=${encodeURIComponent(url)}&media=${encodeURIComponent(currentShareData.image || '')}&description=${encodeURIComponent(title)}`;
        break;
      case 'linkedin':
        shareUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`;
        break;
      case 'email':
        shareUrl = `mailto:?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(shareText + '\n\n' + url)}`;
        break;
      default:
        return;
    }

    if (platform === 'email') {
      window.location.href = shareUrl;
    } else {
      window.open(shareUrl, '_blank', 'noopener,noreferrer,width=640,height=560');
    }
  }

  function openShareModal(options) {
    const overlay = ensureModalInDOM();

    // Resolve post title
    let title = options?.title || '';
    if (!title) {
      const titleEl = document.querySelector('.post-title') || document.getElementById('post-header-title') || document.querySelector('h1') || document.getElementById('pinned-title-link');
      title = titleEl ? titleEl.textContent.trim() : document.title;
    }

    // Resolve post description
    let description = options?.description || '';
    if (!description) {
      const descEl = document.querySelector('.post-lead-excerpt') || document.querySelector('.post-deck') || document.getElementById('pinned-post-desc') || document.querySelector('meta[name="description"]');
      if (descEl) {
        description = descEl.getAttribute('content') || descEl.textContent.trim();
      }
    }

    // Resolve image
    let image = options?.image || '';
    if (!image) {
      const imgEl = document.querySelector('.post-figure img') || document.querySelector('.pinned-image-box img') || document.querySelector('.carousel-slide.is-active img') || document.querySelector('meta[property="og:image"]');
      if (imgEl) {
        image = imgEl.getAttribute('src') || imgEl.getAttribute('content') || DEFAULT_IMAGE;
      } else {
        image = DEFAULT_IMAGE;
      }
    }

    // Resolve URL
    let url = options?.url || window.location.href;

    currentShareData = { title, description, image, url };

    // Update DOM
    const titleEl = document.getElementById('share-preview-title');
    const descEl = document.getElementById('share-preview-desc');
    const imgEl = document.getElementById('share-preview-img');
    const urlInput = document.getElementById('share-url-input');

    if (titleEl) titleEl.textContent = title;
    if (descEl) descEl.textContent = description;
    if (imgEl) {
      imgEl.src = image;
      imgEl.alt = title;
    }
    if (urlInput) {
      urlInput.value = url;
    }

    overlay.classList.add('is-active');
    overlay.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
  }

  function closeShareModal() {
    const overlay = document.getElementById('share-modal-overlay');
    if (overlay) {
      overlay.classList.remove('is-active');
      overlay.setAttribute('aria-hidden', 'true');
    }
    document.body.style.overflow = '';
  }

  // Expose global methods
  window.openShareModal = openShareModal;
  window.closeShareModal = closeShareModal;

  // Auto-bind to share buttons on page load
  document.addEventListener('DOMContentLoaded', () => {
    ensureModalInDOM();

    // 1. Post page header share button
    const postShareBtn = document.getElementById('post-share-btn');
    if (postShareBtn) {
      postShareBtn.addEventListener('click', (e) => {
        e.preventDefault();
        openShareModal();
      });
    }

    // 2. Home page pinned post share button
    const pinnedShareBtn = document.getElementById('pinned-share-btn');
    if (pinnedShareBtn) {
      pinnedShareBtn.addEventListener('click', (e) => {
        e.preventDefault();
        const pinnedTitleEl = document.getElementById('pinned-title-link');
        const pinnedDescEl = document.getElementById('pinned-post-desc');
        const title = pinnedTitleEl ? pinnedTitleEl.textContent.trim() : 'Acute Ischemic Stroke: Multiphase CTA Collateral Atlas & ASPECTS Triage Protocol';
        const description = pinnedDescEl ? pinnedDescEl.textContent.trim() : 'Comprehensive acute neurovascular imaging pathway covering rapid collateral grading, early ischemic core mapping, and standardized acute triage.';
        const url = window.location.origin + '/post/?id=neuroradiology-stroke-cta';
        const image = 'https://images.unsplash.com/photo-1516549655169-df83a0774514?auto=format&fit=crop&w=600&q=80';
        openShareModal({ title, description, url, image });
      });
    }

    // 3. Delegated listener for any share trigger across the DOM
    document.addEventListener('click', (e) => {
      const shareTrigger = e.target.closest('#post-share-btn, #pinned-share-btn, [data-action="share"], .share-trigger');
      if (shareTrigger && !e.defaultPrevented) {
        e.preventDefault();
        openShareModal();
      }
    });
  });

})();


/**
 * blog.js - Central Content & Feed Controller
 * 
 * Powered by POSTS_DATA schema:
 * - Pinned Post dynamic rendering (pinned: true)
 * - Popular Posts dynamic ranking (popular.enabled, position: 1..5)
 * - Topic counters dynamic stimulation & topic filtering
 * - Multi-field real-time search with keyword highlight & instant grid filtering
 * - Blog grid cards with real-image skeleton shimmer, direct image link copying,
 *   and related post resolution.
 */
(function () {
  'use strict';

  // Load posts from central POSTS_DATA
  let POSTS = (typeof window !== 'undefined' && Array.isArray(window.POSTS_DATA)) ? window.POSTS_DATA : [];

  const ITEMS_PER_PAGE = 6;
  let activePosts = [...POSTS];
  let currentPage = 1;
  let currentPaginationToken = 0;
  let activeFilterLabel = null;

  // Single SVG templates: Plus when not bookmarked, Minus when bookmarked
  const SVG_BOOKMARK_PLUS = `<svg class="blog-save-svg" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
    <path d="M14.5 10.6504H9.5" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
    <path d="M12 8.21094V13.2109" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
    <path d="M16.8199 2H7.17995C5.04995 2 3.31995 3.74 3.31995 5.86V19.95C3.31995 21.75 4.60995 22.51 6.18995 21.64L11.0699 18.93C11.5899 18.64 12.4299 18.64 12.9399 18.93L17.8199 21.64C19.3999 22.52 20.6899 21.76 20.6899 19.95V5.86C20.6799 3.74 18.9499 2 16.8199 2Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
  </svg>`;

  const SVG_BOOKMARK_MINUS = `<svg class="blog-save-svg" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
    <path d="M14.5 10.6504H9.5" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
    <path d="M16.8199 2H7.17995C5.04995 2 3.31995 3.74 3.31995 5.86V19.95C3.31995 21.75 4.60995 22.51 6.18995 21.64L11.0699 18.93C11.5899 18.64 12.4299 18.64 12.9399 18.93L17.8199 21.64C19.3999 22.52 20.6899 21.76 20.6899 19.95V5.86C20.6799 3.74 18.9499 2 16.8199 2Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
  </svg>`;

  // Cookie & Local Storage Bookmarks Sync
  let savedPosts = new Set();
  function syncSavedPostsFromStorage() {
    if (window.RadiologyAuth && typeof window.RadiologyAuth.getBookmarks === 'function') {
      savedPosts = new Set(window.RadiologyAuth.getBookmarks());
    } else {
      try {
        const stored = localStorage.getItem('radiology_saved_protocols') || localStorage.getItem('radiology_saved_posts');
        if (stored) {
          const parsed = JSON.parse(stored);
          if (Array.isArray(parsed)) {
            savedPosts = new Set(parsed);
          }
        }
      } catch (err) {
        savedPosts = new Set();
      }
    }
  }
  syncSavedPostsFromStorage();
  window.addEventListener('bookmarks-updated', syncSavedPostsFromStorage);


  /**
   * Helper: Format ISO date string (YYYY-MM-DD) into readable format
   */
  function formatDate(dateStr) {
    if (!dateStr) return '';
    try {
      const [year, month, day] = dateStr.split('-');
      if (!year || !month || !day) return dateStr;
      const months = [
        'January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'
      ];
      const mIdx = parseInt(month, 10) - 1;
      return `${months[mIdx] || month} ${parseInt(day, 10)}, ${year}`;
    } catch {
      return dateStr;
    }
  }

  /**
   * 1. Dynamic Pinned Post Rendering
   * Finds the post marked pinned: true (or falls back to first post)
   */
  function renderPinnedPost() {
    const pinnedPost = POSTS.find((p) => p.pinned === true) || POSTS[0];
    if (!pinnedPost) return;

    const dateElem = document.getElementById('pinned-meta-date');
    const timeElem = document.getElementById('pinned-meta-time');
    const titleLink = document.getElementById('pinned-title-link');
    const descElem = document.getElementById('pinned-post-desc');
    const highlightsContainer = document.getElementById('pinned-highlights');
    const readBtn = document.getElementById('pinned-read-btn');

    if (dateElem) {
      dateElem.textContent = formatDate(pinnedPost.publishedAt);
    }
    if (timeElem) {
      const clockSvg = `
        <svg class="pinned-meta-icon" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <g clip-path="url(#clip0_clock_icon)">
            <path d="M22 12C22 17.52 17.52 22 12 22C6.48 22 2 17.52 2 12C2 6.48 6.48 2 12 2C17.52 2 22 6.48 22 12Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
            <path d="M15.71 15.1798L12.61 13.3298C12.07 13.0098 11.63 12.2398 11.63 11.6098V7.50977" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
          </g>
          <defs>
            <clipPath id="clip0_clock_icon">
              <rect width="24" height="24" fill="white"/>
            </clipPath>
          </defs>
        </svg>
        <span>${pinnedPost.readTime || '7 min read'}</span>
      `;
      timeElem.innerHTML = clockSvg;
    }
    if (titleLink) {
      titleLink.textContent = pinnedPost.title;
      titleLink.setAttribute('href', pinnedPost.url);
    }
    if (descElem) {
      descElem.textContent = pinnedPost.description;
    }
    if (readBtn) {
      readBtn.setAttribute('href', pinnedPost.url);
    }

    if (highlightsContainer && Array.isArray(pinnedPost.tags) && pinnedPost.tags.length > 0) {
      highlightsContainer.innerHTML = pinnedPost.tags.slice(0, 3).map((tag, idx) => `
        <a href="#tag-${tag.toLowerCase().replace(/[^a-z0-9]+/g, '-')}" class="pinned-highlight-item" id="pinned-highlight-${idx + 1}" data-tag="${tag}">
          <svg class="pinned-tag-hash-icon" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M10 3L8 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
            <path d="M16 3L14 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
            <path d="M3.5 9H21.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
            <path d="M2.5 15H20.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
          </svg>
          <span>${tag}</span>
        </a>
      `).join('');

      // Clicking any tag filters the blog grid
      highlightsContainer.querySelectorAll('.pinned-highlight-item').forEach(el => {
        el.addEventListener('click', (e) => {
          e.preventDefault();
          const tag = el.getAttribute('data-tag');
          if (tag) filterByTerm(tag, `Tag: ${tag}`);
        });
      });
    }
  }

  /**
   * 2. Dynamic Popular Posts Sidebar Rendering
   * Sorts popular.enabled: true by popular.position (1 = hero card, 2..5 = text rows)
   */
  function renderPopularPosts() {
    const popularPosts = POSTS
      .filter((p) => p.popular && p.popular.enabled)
      .sort((a, b) => (a.popular.position || 99) - (b.popular.position || 99));

    if (!popularPosts.length) return;

    const featuredContainer = document.querySelector('.popular-featured-post');
    const textListContainer = document.querySelector('.popular-text-list');

    // Post 1: Hero-style Card with Image Overlayed by Text
    const post1 = popularPosts.find((p) => p.popular.position === 1) || popularPosts[0];
    if (featuredContainer && post1) {
      featuredContainer.innerHTML = `
        <a href="${post1.url}" class="popular-overlay-card" aria-label="Popular Post # 1: ${post1.title}">
          <img
            src="${post1.thumbnail}"
            alt="${post1.alt || post1.title}"
            class="popular-overlay-img"
            loading="lazy"
            referrerPolicy="no-referrer"
          />
          <div class="popular-overlay-scrim" aria-hidden="true"></div>

          <div class="popular-overlay-body">
            <div class="popular-overlay-top">
              <span class="popular-rank-pill rank-top">
                <svg class="popular-rank-hash-icon" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M10 3L8 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                  <path d="M16 3L14 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                  <path d="M3.5 9H21.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                  <path d="M2.5 15H20.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                </svg>
                <span>1</span>
              </span>
              <span class="popular-overlay-tag">
                <svg class="popular-tag-hash-icon" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M10 3L8 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                  <path d="M16 3L14 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                  <path d="M3.5 9H21.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                  <path d="M2.5 15H20.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                </svg>
                ${post1.Topic}
              </span>
            </div>
            <h4 class="popular-overlay-title">${post1.title}</h4>
            <p class="popular-overlay-desc">${post1.description}</p>
            <div class="popular-overlay-meta">
              <span>${post1.readTime || '5 min read'}</span>
              <span class="meta-dot" aria-hidden="true">•</span>
              <span>${formatDate(post1.publishedAt)}</span>
            </div>
          </div>
        </a>
      `;
    }

    // Posts 2 through 5: Ranked text list items
    const remainingPosts = popularPosts.filter((p) => p !== post1).slice(0, 4);
    if (textListContainer && remainingPosts.length > 0) {
      textListContainer.innerHTML = remainingPosts
        .map((post, idx) => {
          const rankNum = post.popular.position || (idx + 2);
          return `
          <article class="popular-text-item">
            <a href="${post.url}" class="popular-text-link" aria-label="Popular Post # ${rankNum}: ${post.title}">
              <span class="popular-rank-pill">
                <svg class="popular-rank-hash-icon" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M10 3L8 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                  <path d="M16 3L14 21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                  <path d="M3.5 9H21.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                  <path d="M2.5 15H20.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                </svg>
                <span>${rankNum}</span>
              </span>
              <div class="popular-text-content">
                <h4 class="popular-text-title">${post.title}</h4>
                <div class="popular-meta-row">
                  <span class="popular-meta-tag">${post.Topic}</span>
                  <span class="popular-meta-dot" aria-hidden="true">•</span>
                  <span class="popular-meta-time">${post.readTime || '4 min read'}</span>
                </div>
              </div>
            </a>
          </article>
        `;
        })
        .join('');
    }
  }

  /**
   * 3. Topic Counts Dynamic Stimulation
   * Computes article count per topic and updates the sidebar chips
   */
  function updateTopicCounts() {
    const topicCounts = {};
    const uniqueTopics = new Set();

    POSTS.forEach((p) => {
      const top = (p.Topic || '').trim();
      if (top) {
        uniqueTopics.add(top);
        const key = top.toLowerCase();
        topicCounts[key] = (topicCounts[key] || 0) + 1;
      }
      if (Array.isArray(p.tags)) {
        p.tags.forEach((tag) => {
          const tKey = tag.toLowerCase();
          topicCounts[tKey] = (topicCounts[tKey] || 0) + 1;
        });
      }
    });

    // Update count badge
    const badge = document.getElementById('topics-count-badge');
    if (badge) {
      badge.textContent = `${uniqueTopics.size} Categories`;
    }

    // Mapping between data-topic attributes and topic keywords
    const topicMap = {
      'neuroradiology': ['neuroradiology', 'neuro', 'brain', 'spine'],
      'chest-ct': ['chest ct', 'chest', 'hrct', 'thoracic', 'pulmonary'],
      'musculoskeletal': ['musculoskeletal', 'msk', 'gout', 'rotator'],
      'nuclear-medicine': ['nuclear medicine', 'nuclear med', 'pet-ct', 'oncology'],
      'interventional': ['interventional', 'intervention', 'fluoroscopy', 'angiography'],
      'pediatric': ['pediatrics', 'pediatric', 'neonatal'],
      'radiation-safety': ['safety / qa', 'radiation safety', 'alara', 'physics'],
      'gastrointestinal': ['abdominal', 'abdomen', 'liver', 'hepatobiliary', 'gastrointestinal'],
      'cardiac-mri': ['cardiac mri', 'cardiology', 'heart'],
      'emergency': ['emergency', 'trauma'],
      'head-neck': ['head & neck', 'head neck'],
      'ultrasound': ['ultrasound', 'neurosonography']
    };

    document.querySelectorAll('.topic-item').forEach((item) => {
      const dataTopic = item.getAttribute('data-topic');
      const countSpan = item.querySelector('.topic-count');
      if (!dataTopic || !countSpan) return;

      const synonyms = topicMap[dataTopic] || [dataTopic];
      let matchCount = 0;

      // Count posts matching any of the synonyms in Topic or tags
      POSTS.forEach((post) => {
        const postTopic = (post.Topic || '').toLowerCase();
        const postTags = (post.tags || []).map((t) => t.toLowerCase());
        const hasMatch = synonyms.some(
          (syn) => postTopic.includes(syn) || postTags.some((tag) => tag.includes(syn))
        );
        if (hasMatch) matchCount++;
      });

      // Stimulate count with formatted double-digit string
      const displayCount = String(matchCount).padStart(2, '0');
      countSpan.textContent = `(${displayCount})`;

      // Attach click to filter blog grid by this topic
      item.onclick = (e) => {
        if (!document.getElementById('blog-grid')) {
          // On secondary pages (e.g. /books/), navigate directly to homepage anchor
          window.location.href = `../index.html#topic-${dataTopic}`;
          return;
        }
        e.preventDefault();
        const nameSpan = item.querySelector('.topic-name');
        const topicName = nameSpan ? nameSpan.textContent.trim() : dataTopic;
        filterByTopic(synonyms, topicName);
      };
    });
  }

  /**
   * Filter posts by a topic synonym list
   */
  function filterByTopic(synonyms, displayLabel) {
    activePosts = POSTS.filter((post) => {
      const postTopic = (post.Topic || '').toLowerCase();
      const postTags = (post.tags || []).map((t) => t.toLowerCase());
      return synonyms.some(
        (syn) => postTopic.includes(syn) || postTags.some((tag) => tag.includes(syn))
      );
    });

    activeFilterLabel = `Topic: "${displayLabel}"`;
    currentPage = 1;
    updateFilterUI();
    renderBlogGrid();
    scrollToBlog();
  }

  /**
   * Filter posts by generic search term
   */
  function filterByTerm(term, displayLabel) {
    const q = term.toLowerCase().trim();
    if (!q) {
      clearFilter();
      return;
    }

    activePosts = POSTS.filter((post) => {
      const inTitle = (post.title || '').toLowerCase().includes(q);
      const inDesc = (post.description || '').toLowerCase().includes(q);
      const inTopic = (post.Topic || '').toLowerCase().includes(q);
      const inTags = (post.tags || []).some((t) => t.toLowerCase().includes(q));
      const inKeywords = (post.search?.keywords || []).some((k) => k.toLowerCase().includes(q));
      return inTitle || inDesc || inTopic || inTags || inKeywords;
    });

    activeFilterLabel = displayLabel || `Search: "${term}"`;
    currentPage = 1;
    updateFilterUI();
    renderBlogGrid();
    scrollToBlog();
  }

  /**
   * Clear active filter and restore all posts
   */
  function clearFilter() {
    activePosts = [...POSTS];
    activeFilterLabel = null;
    currentPage = 1;
    updateFilterUI();
    renderBlogGrid();
  }

  function updateFilterUI() {
    const indicator = document.getElementById('blog-filter-indicator');
    const filterText = document.getElementById('blog-filter-text');
    const countBadge = document.getElementById('blog-count-badge');

    if (countBadge) {
      countBadge.textContent = `${activePosts.length} Articles`;
    }

    if (indicator && filterText) {
      if (activeFilterLabel) {
        indicator.style.display = 'inline-flex';
        filterText.innerHTML = `Filtered by: <strong>${activeFilterLabel}</strong> (${activePosts.length} found)`;
      } else {
        indicator.style.display = 'none';
      }
    }
  }

  function scrollToBlog() {
    const section = document.getElementById('blog-section');
    if (section) {
      const rect = section.getBoundingClientRect();
      window.scrollTo({
        top: window.pageYOffset + rect.top - 70,
        behavior: 'smooth'
      });
    }
  }

  /**
   * 4. Blog Grid Rendering & Real Image Shimmer Loader
   */
  function renderBlogGrid() {
    const grid = document.getElementById('blog-grid');
    if (!grid) return;

    currentPaginationToken++;
    const sessionToken = currentPaginationToken;

    const totalPages = Math.max(1, Math.ceil(activePosts.length / ITEMS_PER_PAGE));
    if (currentPage > totalPages) currentPage = 1;

    const startIdx = (currentPage - 1) * ITEMS_PER_PAGE;
    const endIdx = startIdx + ITEMS_PER_PAGE;
    const items = activePosts.slice(startIdx, endIdx);

    if (items.length === 0) {
      grid.innerHTML = `
        <div style="grid-column: 1 / -1; padding: 48px 16px; text-align: center; color: var(--color-text-tertiary);">
          <p style="font-size: 15px; font-weight: 600; color: var(--color-text-secondary); margin-bottom: 8px;">No matching clinical articles found</p>
          <p style="font-size: 13px; margin-bottom: 16px;">Try adjusting your search terms or browse by topic.</p>
          <button type="button" class="search-action-btn" id="empty-state-reset-btn" style="padding: 6px 14px; font-size: 12px; margin: 0 auto;">
            Reset All Articles
          </button>
        </div>
      `;
      const resetBtn = document.getElementById('empty-state-reset-btn');
      if (resetBtn) resetBtn.onclick = clearFilter;
      renderPagination(0);
      return;
    }

    grid.innerHTML = items
      .map((item) => {
        const isSaved = savedPosts.has(item.id);
        const iconSvg = isSaved ? SVG_BOOKMARK_MINUS : SVG_BOOKMARK_PLUS;
        const formattedDate = formatDate(item.publishedAt);
        const relatedCount = Array.isArray(item.related) ? item.related.length : 0;
        const primaryTag = Array.isArray(item.tags) && item.tags.length > 0 ? item.tags[0] : item.Topic;

        return `
        <article class="blog-card" id="${item.id}" data-slug="${item.slug}">
          <div class="blog-card-media is-loading" aria-label="${item.title}">
            <!-- Image skeleton shimmer placeholder -->
            <div class="blog-card-skeleton" aria-hidden="true">
              <div class="blog-skeleton-shimmer"></div>
              <div class="blog-skeleton-icon">
                <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                  <rect width="18" height="18" x="3" y="3" rx="2" ry="2"/>
                  <circle cx="9" cy="9" r="2"/>
                  <path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/>
                </svg>
              </div>
            </div>

            <!-- Real Article Thumbnail -->
            <img
              src="${item.thumbnail}"
              alt="${item.alt || item.title}"
              class="blog-card-img"
              loading="lazy"
              referrerPolicy="no-referrer"
              decoding="async"
            />

            <!-- Error fallback -->
            <div class="blog-card-img-fallback" aria-hidden="true">
              <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
                <circle cx="12" cy="12" r="10"></circle>
                <line x1="12" y1="8" x2="12" y2="12"></line>
                <line x1="12" y1="16" x2="12.01" y2="16"></line>
              </svg>
              <span class="blog-fallback-text">Image unavailable</span>
            </div>

            <!-- Save Protocol Button -->
            <button
              type="button"
              class="blog-card-save-btn ${isSaved ? 'is-saved' : ''}"
              aria-label="${isSaved ? 'Remove saved protocol' : 'Save protocol'}"
              data-post-id="${item.id}"
              title="${isSaved ? 'Saved' : 'Save'}"
            >
              <span class="blog-card-save-text">${isSaved ? 'Saved' : 'Save'}</span>
              <span class="blog-card-save-icon">
                ${iconSvg}
              </span>
            </button>
          </div>

          <div class="blog-card-body">
            <div class="blog-card-meta">
              <span class="blog-card-in">in</span>
              <span class="blog-card-labels">${item.Topic}</span>
              ${relatedCount > 0 ? `<span class="blog-card-related-badge" title="Has ${relatedCount} related clinical protocols">${relatedCount} Related</span>` : ''}
            </div>

            <a href="${item.url}" class="blog-card-title-link">
              <h4 class="blog-card-title">${item.title}</h4>
            </a>

            <p class="blog-card-excerpt">${item.description}</p>
          </div>

          <div class="blog-card-footer">
            <span class="blog-card-date">${formattedDate}</span>
            <a href="${item.url}" class="blog-card-read-label" aria-label="Read Protocol: ${item.title}">
              <span>Read Protocol</span>
              <svg class="blog-card-chevron" xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                <path d="M8.9502 4.08008L15.4702 10.6001C16.2402 11.3701 16.2402 12.6301 15.4702 13.4001L8.9502 19.9201" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
              </svg>
            </a>
          </div>
        </article>
      `;
      })
      .join('');

    attachSaveListeners();
    setupCardImageLoaders(sessionToken);
    renderPagination(totalPages);
  }

  function setupCardImageLoaders(pageSessionToken) {
    const grid = document.getElementById('blog-grid');
    if (!grid) return;

    const cards = grid.querySelectorAll('.blog-card');
    cards.forEach((card) => {
      const media = card.querySelector('.blog-card-media');
      const img = card.querySelector('.blog-card-img');
      const skeleton = card.querySelector('.blog-card-skeleton');
      const fallback = card.querySelector('.blog-card-img-fallback');

      if (!media || !img) return;

      let handled = false;

      function onLoaded() {
        if (handled) return;
        handled = true;
        if (pageSessionToken !== currentPaginationToken) return;

        media.classList.remove('is-loading');
        media.classList.add('is-loaded');
      }

      function onError() {
        if (handled) return;
        handled = true;
        if (pageSessionToken !== currentPaginationToken) return;

        media.classList.remove('is-loading');
        media.classList.add('is-error');
        if (skeleton) skeleton.style.display = 'none';
        if (fallback) fallback.style.display = 'flex';
      }

      if (img.complete) {
        if (img.naturalWidth > 0) {
          onLoaded();
        } else {
          onError();
        }
      } else {
        img.addEventListener('load', onLoaded, { once: true });
        img.addEventListener('error', onError, { once: true });
      }
    });
  }

  function handleSaveToggle(e) {
    e.preventDefault();
    e.stopPropagation();

    const btn = e.currentTarget;
    const postId = btn.getAttribute('data-post-id');
    if (!postId) return;

    const labelSpan = btn.querySelector('.blog-card-save-text');
    const iconSpan = btn.querySelector('.blog-card-save-icon');

    if (window.RadiologyAuth && typeof window.RadiologyAuth.toggleBookmark === 'function') {
      const isSaved = window.RadiologyAuth.toggleBookmark(postId);
      if (isSaved) {
        savedPosts.add(postId);
        btn.classList.add('is-saved');
        btn.setAttribute('aria-label', 'Remove saved protocol');
        btn.setAttribute('title', 'Saved');
        if (labelSpan) labelSpan.textContent = 'Saved';
        if (iconSpan) iconSpan.innerHTML = SVG_BOOKMARK_MINUS;
        if (window.RadiologyAuth.showToast) {
          window.RadiologyAuth.showToast('Bookmark saved to your account (Cookie)', 'success');
        }
      } else {
        savedPosts.delete(postId);
        btn.classList.remove('is-saved');
        btn.setAttribute('aria-label', 'Save protocol');
        btn.setAttribute('title', 'Save');
        if (labelSpan) labelSpan.textContent = 'Save';
        if (iconSpan) iconSpan.innerHTML = SVG_BOOKMARK_PLUS;
        if (window.RadiologyAuth.showToast) {
          window.RadiologyAuth.showToast('Bookmark removed from your account', 'info');
        }
      }
    } else {
      if (savedPosts.has(postId)) {
        savedPosts.delete(postId);
        btn.classList.remove('is-saved');
        btn.setAttribute('aria-label', 'Save protocol');
        btn.setAttribute('title', 'Save');
        if (labelSpan) labelSpan.textContent = 'Save';
        if (iconSpan) iconSpan.innerHTML = SVG_BOOKMARK_PLUS;
      } else {
        savedPosts.add(postId);
        btn.classList.add('is-saved');
        btn.setAttribute('aria-label', 'Remove saved protocol');
        btn.setAttribute('title', 'Saved');
        if (labelSpan) labelSpan.textContent = 'Saved';
        if (iconSpan) iconSpan.innerHTML = SVG_BOOKMARK_MINUS;
      }

      try {
        localStorage.setItem('radiology_saved_protocols', JSON.stringify([...savedPosts]));
      } catch (err) {}
    }
  }

  function attachSaveListeners() {
    const saveBtns = document.querySelectorAll('.blog-card-save-btn');
    saveBtns.forEach((btn) => {
      btn.removeEventListener('click', handleSaveToggle);
      btn.addEventListener('click', handleSaveToggle);
    });
  }

  function goToPage(pageNum, totalPages) {
    if (pageNum < 1 || pageNum > totalPages || pageNum === currentPage) return;
    currentPage = pageNum;
    renderBlogGrid();
    scrollToBlog();
  }

  function renderPagination(totalPages) {
    const homeBtn = document.getElementById('pagination-home-btn');
    const prevBtn = document.getElementById('pagination-prev-btn');
    const nextBtn = document.getElementById('pagination-next-btn');
    const numbersContainer = document.getElementById('pagination-numbers');

    if (homeBtn) {
      homeBtn.disabled = currentPage === 1;
      homeBtn.setAttribute('aria-disabled', String(currentPage === 1));
      homeBtn.onclick = () => goToPage(1, totalPages);
    }

    if (prevBtn) {
      prevBtn.disabled = currentPage === 1;
      prevBtn.setAttribute('aria-disabled', String(currentPage === 1));
      prevBtn.onclick = () => goToPage(currentPage - 1, totalPages);
    }

    if (nextBtn) {
      nextBtn.disabled = currentPage >= totalPages;
      nextBtn.setAttribute('aria-disabled', String(currentPage >= totalPages));
      nextBtn.onclick = () => goToPage(currentPage + 1, totalPages);
    }

    if (!numbersContainer) return;

    if (totalPages <= 1) {
      numbersContainer.innerHTML = `
        <button type="button" class="pagination-number is-active" data-page="1" aria-current="page">1</button>
      `;
      return;
    }

    let html = '';
    for (let i = 1; i <= totalPages; i++) {
      const isActive = i === currentPage;
      html += `
        <button
          type="button"
          class="pagination-number ${isActive ? 'is-active' : ''}"
          data-page="${i}"
          aria-current="${isActive ? 'page' : 'false'}"
          aria-label="Go to page ${i}"
        >
          ${i}
        </button>
      `;
    }

    numbersContainer.innerHTML = html;

    numbersContainer.querySelectorAll('.pagination-number').forEach((btn) => {
      btn.addEventListener('click', function () {
        const page = parseInt(this.getAttribute('data-page'), 10);
        if (page && page !== currentPage) {
          goToPage(page, totalPages);
        }
      });
    });
  }

  /**
   * 5. Multi-field Real-Time Search Engine
   * Matches title, description, Topic, tags, and search.keywords
   */
  function initSearchEngine() {
    const searchInput = document.getElementById('search-input');
    const searchForm = document.getElementById('search-form');
    const searchResults = document.getElementById('search-modal-results');
    const clearBtn = document.getElementById('search-clear-btn');
    const modalOverlay = document.getElementById('search-modal-overlay');

    if (!searchInput || !searchResults) return;

    function highlightText(text, query) {
      if (!query || !text) return text;
      const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const regex = new RegExp(`(${escaped})`, 'gi');
      return text.replace(regex, '<mark class="search-highlight">$1</mark>');
    }

    function renderDefaultSearchState() {
      searchResults.innerHTML = `
        <div class="search-empty-state">
          <p class="search-empty-title">Suggested Clinical Topics</p>
          <div class="search-empty-tags">
            <button type="button" class="search-suggested-tag" data-tag="Neuroradiology">Neuroradiology</button>
            <button type="button" class="search-suggested-tag" data-tag="CT">Computed Tomography</button>
            <button type="button" class="search-suggested-tag" data-tag="MRI">Magnetic Resonance</button>
            <button type="button" class="search-suggested-tag" data-tag="Emergency">Emergency Trauma</button>
            <button type="button" class="search-suggested-tag" data-tag="Ultrasound">Ultrasound</button>
            <button type="button" class="search-suggested-tag" data-tag="Intervention">Intervention</button>
          </div>
        </div>
      `;

      searchResults.querySelectorAll('.search-suggested-tag').forEach((btn) => {
        btn.onclick = (e) => {
          if (e) {
            e.preventDefault();
            e.stopPropagation();
          }
          const tag = btn.getAttribute('data-tag');
          if (tag) {
            searchInput.value = tag;
            if (clearBtn) clearBtn.classList.add('is-visible');
            performSearch(tag);
            searchInput.focus();
          }
        };
      });
    }

    function performSearch(query) {
      const q = query.trim().toLowerCase();
      if (!q) {
        renderDefaultSearchState();
        return;
      }

      // Multi-field scoring
      const matches = POSTS.map((post) => {
        let score = 0;
        const titleLower = (post.title || '').toLowerCase();
        const descLower = (post.description || '').toLowerCase();
        const topicLower = (post.Topic || '').toLowerCase();
        const tags = (post.tags || []).map((t) => t.toLowerCase());
        const keywords = (post.search?.keywords || []).map((k) => k.toLowerCase());

        if (titleLower.includes(q)) score += 10;
        if (topicLower.includes(q)) score += 8;
        if (keywords.some((k) => k.includes(q))) score += 7;
        if (tags.some((t) => t.includes(q))) score += 6;
        if (descLower.includes(q)) score += 4;

        return { post, score };
      })
        .filter((item) => item.score > 0)
        .sort((a, b) => b.score - a.score)
        .map((item) => item.post);

      if (matches.length === 0) {
        searchResults.innerHTML = `
          <div class="search-empty-state">
            <p class="search-empty-title">No notes or protocols found for "${query}"</p>
            <p class="search-empty-desc">Try synonyms like "CT", "MRI", "Stroke", "Trauma", or "LGE"</p>
          </div>
        `;
        return;
      }

      searchResults.innerHTML = `
        <div class="search-results-summary">
          <span class="search-results-count">Found ${matches.length} ${matches.length === 1 ? 'article' : 'articles'}</span>
        </div>
        <div class="search-results-items-list">
          ${matches.map((post) => `
            <div class="search-result-item" data-id="${post.id}" data-url="${post.url}" tabindex="0" role="button" aria-label="Open ${post.title}">
              <div class="search-result-content">
                <div class="search-result-meta">
                  <span class="search-result-in">in</span>
                  <span class="search-result-labels">${post.Topic}</span>
                </div>
                <h4 class="search-result-title">${highlightText(post.title, query)}</h4>
                <p class="search-result-desc">${highlightText(post.description, query)}</p>
              </div>
            </div>
          `).join('')}
        </div>
        <div class="search-filter-grid-action-wrap">
          <button type="button" class="search-filter-grid-action-btn" id="search-filter-grid-action-btn" title="Filter the blog grid with this query">
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon>
            </svg>
            <span>CLICK TO FILTER GRID</span>
          </button>
        </div>
      `;

      // CLICK TO FILTER GRID action button
      const filterGridBtn = searchResults.querySelector('#search-filter-grid-action-btn');
      if (filterGridBtn) {
        filterGridBtn.addEventListener('click', (e) => {
          e.preventDefault();
          e.stopPropagation();
          closeSearchModal();
          const blogSection = document.getElementById('blog-posts') || document.getElementById('blog-grid');
          if (blogSection) {
            filterByTerm(query, `Query: "${query}"`);
            blogSection.scrollIntoView({ behavior: 'smooth' });
          } else {
            // On secondary subpages (e.g. /books/), store query and navigate to homepage
            sessionStorage.setItem('radiology_pending_filter', query);
            window.location.href = `../index.html#blog-posts`;
          }
        });
      }

      // Click on post result directly: navigate to that page/post with NO grid filter
      searchResults.querySelectorAll('.search-result-item').forEach((item) => {
        const navigateDirectly = (e) => {
          e.preventDefault();
          e.stopPropagation();
          const targetUrl = item.getAttribute('data-url');
          closeSearchModal();
          if (targetUrl) {
            if (targetUrl.startsWith('#')) {
              const targetEl = document.querySelector(targetUrl) || document.getElementById(targetUrl.replace(/^#/, ''));
              if (targetEl) {
                targetEl.scrollIntoView({ behavior: 'smooth' });
              } else {
                if (window.location.pathname.includes('/books') || window.location.pathname.includes('/login') || window.location.pathname.includes('/post')) {
                  window.location.href = `../index.html${targetUrl}`;
                } else {
                  window.location.hash = targetUrl;
                }
              }
            } else {
              window.location.href = targetUrl;
            }
          }
        };

        item.addEventListener('click', navigateDirectly);
        item.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            navigateDirectly(e);
          }
        });
      });
    }

    function closeSearchModal() {
      if (modalOverlay) {
        modalOverlay.classList.remove('is-active');
        modalOverlay.setAttribute('aria-hidden', 'true');
        document.body.classList.remove('modal-open');
      }
    }

    searchInput.addEventListener('input', (e) => {
      performSearch(e.target.value);
    });

    if (searchForm) {
      searchForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const query = searchInput.value.trim();
        if (query) {
          filterByTerm(query, `Query: "${query}"`);
          closeSearchModal();
        }
      });
    }

    if (clearBtn) {
      clearBtn.addEventListener('click', () => {
        searchInput.value = '';
        renderDefaultSearchState();
      });
    }

    // Initial default state
    renderDefaultSearchState();
  }

  /**
   * Initialize Everything
   */
  function initBlog() {
    renderPinnedPost();
    renderPopularPosts();
    updateTopicCounts();
    renderBlogGrid();
    initSearchEngine();

    // Active filter clear button
    const clearFilterBtn = document.getElementById('blog-filter-clear-btn');
    if (clearFilterBtn) {
      clearFilterBtn.addEventListener('click', clearFilter);
    }

    // Expose global methods for external header / drawer integration
    window.radiologySearch = filterByTerm;
    window.radiologyFilterByTopic = filterByTopic;
    window.radiologyClearFilter = clearFilter;

    // Check pending filter from cross-page navigation
    try {
      const pendingQuery = sessionStorage.getItem('radiology_pending_filter');
      if (pendingQuery) {
        sessionStorage.removeItem('radiology_pending_filter');
        filterByTerm(pendingQuery, `Query: "${pendingQuery}"`);
        const blogSection = document.getElementById('blog-posts') || document.getElementById('blog-grid');
        if (blogSection) {
          blogSection.scrollIntoView({ behavior: 'smooth' });
        }
      }
    } catch (e) {
      // ignore
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initBlog);
  } else {
    initBlog();
  }
})();


/**
 * post.js
 * Logic for Post Page interactions:
 * - Bookmark/Save action
 * - Share and copy link
 * - Reading time dynamic counter / Reading progress
 */

(function () {
  'use strict';

  const STORAGE_KEY_SAVED = 'radiology_saved_posts';

  const SVG_SAVE_PLUS = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none">
    <g clip-path="url(#clip0_4418_9959)">
      <path d="M14.5 10.6504H9.5" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
      <path d="M12 8.21094V13.2109" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round" />
      <path d="M16.8199 2H7.17995C5.04995 2 3.31995 3.74 3.31995 5.86V19.95C3.31995 21.75 4.60995 22.51 6.18995 21.64L11.0699 18.93C11.5899 18.64 12.4299 18.64 12.9399 18.93L17.8199 21.64C19.3999 22.52 20.6899 21.76 20.6899 19.95V5.86C20.6799 3.74 18.9499 2 16.8199 2Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
    </g>
    <defs>
      <clipPath id="clip0_4418_9959">
        <rect width="24" height="24" fill="white"/>
      </clipPath>
    </defs>
  </svg>`;

  const SVG_SAVE_CHECK = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none">
    <g clip-path="url(#clip0_4418_9959_chk)">
      <path d="M9 11.5L11 13.5L15 9.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
      <path d="M16.8199 2H7.17995C5.04995 2 3.31995 3.74 3.31995 5.86V19.95C3.31995 21.75 4.60995 22.51 6.18995 21.64L11.0699 18.93C11.5899 18.64 12.4299 18.64 12.9399 18.93L17.8199 21.64C19.3999 22.52 20.6899 21.76 20.6899 19.95V5.86C20.6799 3.74 18.9499 2 16.8199 2Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
    </g>
    <defs>
      <clipPath id="clip0_4418_9959_chk">
        <rect width="24" height="24" fill="white"/>
      </clipPath>
    </defs>
  </svg>`;

  function initPostActions() {
    const saveBtn = document.getElementById('post-save-btn');
    const saveIcon = document.getElementById('post-save-icon');
    const saveText = document.getElementById('post-save-text');
    const shareBtn = document.getElementById('post-share-btn');
    const shareText = document.getElementById('post-share-text');

    const postId = 'stroke-cta-protocol';

    // Read saved status from RadiologyAuth (Cookie-based)
    let isSaved = false;
    if (window.RadiologyAuth && typeof window.RadiologyAuth.isBookmarked === 'function') {
      isSaved = window.RadiologyAuth.isBookmarked(postId);
    } else {
      try {
        const savedList = JSON.parse(localStorage.getItem(STORAGE_KEY_SAVED) || '[]');
        isSaved = savedList.includes(postId);
      } catch (e) {
        isSaved = false;
      }
    }
    updateSaveUI(isSaved);

    function updateSaveUI(saved) {
      if (!saveBtn) return;
      if (saved) {
        saveBtn.classList.add('is-active');
        saveBtn.setAttribute('aria-pressed', 'true');
        saveBtn.setAttribute('title', 'Saved to Bookmarks (Cookie)');
        if (saveText) saveText.textContent = '';
        if (saveIcon) saveIcon.innerHTML = SVG_SAVE_CHECK;
      } else {
        saveBtn.classList.remove('is-active');
        saveBtn.setAttribute('aria-pressed', 'false');
        saveBtn.setAttribute('title', 'Save to Bookmarks');
        if (saveText) saveText.textContent = '';
        if (saveIcon) saveIcon.innerHTML = SVG_SAVE_PLUS;
      }
    }

    if (saveBtn) {
      saveBtn.addEventListener('click', () => {
        if (window.RadiologyAuth && typeof window.RadiologyAuth.toggleBookmark === 'function') {
          isSaved = window.RadiologyAuth.toggleBookmark(postId);
          updateSaveUI(isSaved);
          if (window.RadiologyAuth.showToast) {
            window.RadiologyAuth.showToast(isSaved ? 'Saved to bookmarks' : 'Removed from bookmarks', isSaved ? 'success' : 'info');
          }
        } else {
          isSaved = !isSaved;
          try {
            let list = JSON.parse(localStorage.getItem(STORAGE_KEY_SAVED) || '[]');
            if (isSaved) {
              if (!list.includes(postId)) list.push(postId);
            } else {
              list = list.filter((id) => id !== postId);
            }
            localStorage.setItem(STORAGE_KEY_SAVED, JSON.stringify(list));
          } catch (e) {}
          updateSaveUI(isSaved);
        }
      });
    }

    window.addEventListener('bookmarks-updated', () => {
      if (window.RadiologyAuth) {
        isSaved = window.RadiologyAuth.isBookmarked(postId);
        updateSaveUI(isSaved);
      }
    });

    if (shareBtn) {
      shareBtn.addEventListener('click', () => {
        if (typeof window.openShareModal === 'function') {
          window.openShareModal();
        }
      });
    }

    const commentBtn = document.getElementById('post-comment-btn');
    if (commentBtn) {
      commentBtn.addEventListener('click', () => {
        if (typeof window.openCommentsModal === 'function') {
          window.openCommentsModal();
        }
      });
    }
  }

  /**
   * Interactive Tabs
   */
  function initPostTabs() {
    const tabContainers = document.querySelectorAll('.post-tabs');
    tabContainers.forEach((container) => {
      const btns = container.querySelectorAll('.post-tab-btn');
      const panels = container.querySelectorAll('.post-tab-panel');

      btns.forEach((btn) => {
        btn.addEventListener('click', () => {
          const targetId = btn.getAttribute('data-tab');

          btns.forEach((b) => b.classList.remove('is-active'));
          panels.forEach((p) => p.classList.remove('is-active'));

          btn.classList.add('is-active');
          const activePanel = container.querySelector(`#${targetId}`);
          if (activePanel) {
            activePanel.classList.add('is-active');
          }
        });
      });
    });
  }

  /**
   * Code Block Copy Buttons
   */
  function initCodeCopy() {
    const copySVG = `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 12.9V17.1C16 20.6 14.6 22 11.1 22H6.9C3.4 22 2 20.6 2 17.1V12.9C2 9.4 3.4 8 6.9 8H11.1C14.6 8 16 9.4 16 12.9Z"></path><path d="M22 6.9V11.1C22 14.6 20.6 16 17.1 16H16V12.9C16 9.4 14.6 8 11.1 8H8V6.9C8 3.4 9.4 2 12.9 2H17.1C20.6 2 22 3.4 22 6.9Z"></path></svg>`;
    const checkSVG = `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 11.1V6.9C22 3.4 20.6 2 17.1 2H12.9C9.4 2 8 3.4 8 6.9V8H11.1C14.6 8 16 9.4 16 12.9V16H17.1C20.6 16 22 14.6 22 11.1Z"></path><path d="M16 17.1V12.9C16 9.4 14.6 8 11.1 8H6.9C3.4 8 2 9.4 2 12.9V17.1C2 20.6 3.4 22 6.9 22H11.1C14.6 22 16 20.6 16 17.1Z"></path><path d="M6.08008 15.0008L8.03008 16.9508L11.9201 13.0508"></path></svg>`;

    const copyBtns = document.querySelectorAll('.code-copy-btn');
    copyBtns.forEach((btn) => {
      btn.addEventListener('click', async () => {
        const targetId = btn.getAttribute('data-target');
        const codeElement = targetId ? document.getElementById(targetId) : btn.closest('.post-code-block')?.querySelector('pre code');
        if (!codeElement) return;

        const textToCopy = codeElement.innerText;
        try {
          await navigator.clipboard.writeText(textToCopy);
          btn.innerHTML = checkSVG;
          btn.classList.add('is-copied');
          setTimeout(() => {
            btn.innerHTML = copySVG;
            btn.classList.remove('is-copied');
          }, 2000);
        } catch (e) {
          try {
            const textarea = document.createElement('textarea');
            textarea.value = textToCopy;
            textarea.style.position = 'fixed';
            textarea.style.opacity = '0';
            document.body.appendChild(textarea);
            textarea.select();
            document.execCommand('copy');
            btn.innerHTML = checkSVG;
            btn.classList.add('is-copied');
            setTimeout(() => {
              btn.innerHTML = copySVG;
              btn.classList.remove('is-copied');
            }, 2000);
            document.body.removeChild(textarea);
          } catch (err) {}
        }
      });
    });
  }

  /**
   * Interactive Checklist
   */
  function initChecklist() {
    const checklistItems = document.querySelectorAll('.post-checklist li');
    checklistItems.forEach((item) => {
      const checkbox = item.querySelector('.post-checklist-checkbox');
      item.addEventListener('click', (e) => {
        if (e.target !== checkbox && checkbox) {
          checkbox.checked = !checkbox.checked;
        }
        if (checkbox && checkbox.checked) {
          item.style.opacity = '0.7';
          item.style.textDecoration = 'line-through';
        } else {
          item.style.opacity = '1';
          item.style.textDecoration = 'none';
        }
      });
      if (checkbox) {
        checkbox.addEventListener('change', () => {
          if (checkbox.checked) {
            item.style.opacity = '0.7';
            item.style.textDecoration = 'line-through';
          } else {
            item.style.opacity = '1';
            item.style.textDecoration = 'none';
          }
        });
      }
    });
  }

  /**
   * Smooth Scroll for TOC & In-Page Anchors
   */
  function initSmoothScroll() {
    document.querySelectorAll('.post-toc-link, .post-citation, .post-footnote-backref').forEach((anchor) => {
      anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');
        if (href && href.startsWith('#')) {
          const target = document.querySelector(href);
          if (target) {
            e.preventDefault();
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            history.pushState(null, '', href);
          }
        }
      });
    });
  }

  /**
   * KaTeX Math & Formula Rendering and LaTeX Copy Functionality
   */
  function initMathAndChem() {
    function renderAllFormulas() {
      // 1. Direct KaTeX rendering for targeted display formula blocks
      if (typeof window.katex !== 'undefined' && typeof window.katex.render === 'function') {
        document.querySelectorAll('.post-formula-math[data-latex]').forEach((el) => {
          const latex = el.getAttribute('data-latex');
          if (latex) {
            try {
              window.katex.render(latex, el, {
                displayMode: true,
                throwOnError: false,
                output: 'htmlAndMathml'
              });
            } catch (err) {
              console.warn('KaTeX render error:', err);
            }
          }
        });

        // 2. Direct KaTeX rendering for inline expressions
        document.querySelectorAll('.katex-inline[data-latex]').forEach((el) => {
          const latex = el.getAttribute('data-latex');
          if (latex) {
            try {
              window.katex.render(latex, el, {
                displayMode: false,
                throwOnError: false,
                output: 'htmlAndMathml'
              });
            } catch (err) {
              console.warn('KaTeX inline render error:', err);
            }
          }
        });
      }

      // 3. Auto-render remaining delimiters across post prose
      if (typeof window.renderMathInElement === 'function') {
        const prose = document.querySelector('.post-prose') || document.body;
        try {
          window.renderMathInElement(prose, {
            delimiters: [
              { left: '$$', right: '$$', display: true },
              { left: '$', right: '$', display: false },
              { left: '\\[', right: '\\]', display: true },
              { left: '\\(', right: '\\)', display: false }
            ],
            throwOnError: false,
            ignoredTags: ['script', 'noscript', 'style', 'textarea', 'pre', 'code']
          });
        } catch (e) {
          console.warn('KaTeX auto-render error:', e);
        }
      }
    }

    // Try rendering on load and with retries if scripts are deferred
    if (typeof window.katex !== 'undefined' || typeof window.renderMathInElement === 'function') {
      renderAllFormulas();
    } else {
      window.addEventListener('load', renderAllFormulas);
      setTimeout(renderAllFormulas, 200);
      setTimeout(renderAllFormulas, 800);
      setTimeout(renderAllFormulas, 2000);
    }

    // 4. Formula LaTeX Copy Interaction
    const copySVG = `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 12.9V17.1C16 20.6 14.6 22 11.1 22H6.9C3.4 22 2 20.6 2 17.1V12.9C2 9.4 3.4 8 6.9 8H11.1C14.6 8 16 9.4 16 12.9Z"></path><path d="M22 6.9V11.1C22 14.6 20.6 16 17.1 16H16V12.9C16 9.4 14.6 8 11.1 8H8V6.9C8 3.4 9.4 2 12.9 2H17.1C20.6 2 22 3.4 22 6.9Z"></path></svg>`;
    const checkSVG = `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 11.1V6.9C22 3.4 20.6 2 17.1 2H12.9C9.4 2 8 3.4 8 6.9V8H11.1C14.6 8 16 9.4 16 12.9V16H17.1C20.6 16 22 14.6 22 11.1Z"></path><path d="M16 17.1V12.9C16 9.4 14.6 8 11.1 8H6.9C3.4 8 2 9.4 2 12.9V17.1C2 20.6 3.4 22 6.9 22H11.1C14.6 22 16 20.6 16 17.1Z"></path><path d="M6.08008 15.0008L8.03008 16.9508L11.9201 13.0508"></path></svg>`;

    document.querySelectorAll('.formula-copy-btn').forEach((btn) => {
      btn.addEventListener('click', async function () {
        const latex = this.getAttribute('data-latex') || '';
        if (!latex) return;

        try {
          await navigator.clipboard.writeText(latex);
          this.innerHTML = checkSVG;
          this.classList.add('is-copied');

          setTimeout(() => {
            this.innerHTML = copySVG;
            this.classList.remove('is-copied');
          }, 2000);
        } catch (err) {
          // Fallback textarea copy
          const textarea = document.createElement('textarea');
          textarea.value = latex;
          textarea.style.position = 'fixed';
          textarea.style.opacity = '0';
          document.body.appendChild(textarea);
          textarea.select();
          try {
            document.execCommand('copy');
            this.innerHTML = checkSVG;
            this.classList.add('is-copied');
            setTimeout(() => {
              this.innerHTML = copySVG;
              this.classList.remove('is-copied');
            }, 2000);
          } catch (e) {
            console.error('Failed to copy LaTeX:', e);
          }
          document.body.removeChild(textarea);
        }
      });
    });
  }

  /**
   * Comments & Discussion Modal / Bottom Sheet System
   */
  function initCommentsModal() {
    const overlay = document.getElementById('comments-modal-overlay');
    const modal = document.getElementById('comments-modal');
    const closeBtn = document.getElementById('comments-close-btn');
    const commentsListEl = document.getElementById('comments-list');
    const countBadge = document.getElementById('comments-count-badge');
    const commentForm = document.getElementById('comment-form');
    const commentInput = document.getElementById('comment-input');
    const commentPostPill = document.getElementById('comment-post-pill');
    const commentCurrentAvatarEl = document.getElementById('comment-current-avatar');
    const replyingBanner = document.getElementById('comment-replying-banner');
    const replyingToName = document.getElementById('replying-to-name');
    const cancelReplyBtn = document.getElementById('cancel-reply-btn');
    const sheetHandle = document.getElementById('comments-sheet-handle');

    if (!overlay || !commentsListEl || !commentForm) return;

    // State
    let comments = [];
    let activeReplyTarget = null; // { parentId: string, replyToAuthor: string, isReplyToReply: boolean }
    let expandedReplyIds = new Set(); // Replies hidden by default

    function adjustTextareaHeight() {
      if (!commentInput) return;
      commentInput.style.height = 'auto';
      const newHeight = Math.min(Math.max(commentInput.scrollHeight, 38), 140);
      commentInput.style.height = newHeight + 'px';
    }

    function updatePostPillVisibility() {
      if (!commentPostPill || !commentInput) return;
      const hasText = commentInput.value.trim().length > 0;
      commentPostPill.disabled = !hasText;
      commentPostPill.classList.toggle('is-visible', hasText);
    }

    // Helper to get self-hosted DiceBear avatar data URI
    function getDicebearAvatar(seed) {
      if (typeof window !== 'undefined' && window.DiceBear && typeof window.DiceBear.getRandomAvatar === 'function') {
        return window.DiceBear.getRandomAvatar(seed);
      }
      return null;
    }

    // Returns avatar HTML markup: if user has avatarUrl, renders it; if user doesn't have a profile image, randomizes with DiceBear!
    function getAvatarMarkup(item, cssClass = '') {
      let avatarUrl = item.avatarUrl;
      if (!avatarUrl) {
        avatarUrl = getDicebearAvatar(item.author || item.id || 'radiology-user');
      }

      if (avatarUrl) {
        return `<div class="comment-avatar ${cssClass}" title="${escapeHtml(item.author || 'User')}"><img class="comment-avatar-img" src="${avatarUrl}" alt="${escapeHtml(item.author || 'User')}" loading="lazy" /></div>`;
      }
      return `<div class="comment-avatar ${cssClass}" style="background-color: ${item.avatarBg || '#0891b2'};">${escapeHtml(item.avatarText || 'MD')}</div>`;
    }

    function updateCurrentAvatarUI() {
      if (!commentCurrentAvatarEl) return;
      let session = null;
      try {
        const raw = localStorage.getItem('my_radiology_user_session');
        if (raw) session = JSON.parse(raw);
      } catch (e) {}

      let currentAvatar = session && session.avatar ? session.avatar : null;
      let userName = session && session.name ? session.name : 'You';

      // If user doesn't have a profile image, randomize with DiceBear
      if (!currentAvatar) {
        let guestAvatar = null;
        try {
          guestAvatar = localStorage.getItem('my_radiology_user_avatar');
        } catch (e) {}
        if (!guestAvatar) {
          guestAvatar = getDicebearAvatar('user-' + Math.random().toString(36).substring(2, 9));
          if (guestAvatar) {
            try {
              localStorage.setItem('my_radiology_user_avatar', guestAvatar);
            } catch (e) {}
          }
        }
        currentAvatar = guestAvatar;
      }

      if (currentAvatar) {
        commentCurrentAvatarEl.innerHTML = `<img class="comment-current-avatar-img" src="${currentAvatar}" alt="${escapeHtml(userName)}" />`;
      } else {
        commentCurrentAvatarEl.innerHTML = `<span>${escapeHtml(userName.substring(0, 2))}</span>`;
      }

      // Check if user is authenticated with Google -> Only Google users can post comments!
      const isGoogle = !!(window.RadiologyAuth && typeof window.RadiologyAuth.isGoogleUser === 'function' ? window.RadiologyAuth.isGoogleUser() : (session && session.provider === 'google'));
      const restrictionEl = document.getElementById('comment-local-restriction');
      if (restrictionEl) {
        restrictionEl.classList.toggle('is-hidden', isGoogle);
      }
      const restrictionLoginBtn = document.getElementById('btn-restriction-google-login');
      if (restrictionLoginBtn && !restrictionLoginBtn.hasAttribute('data-bound')) {
        restrictionLoginBtn.setAttribute('data-bound', 'true');
        restrictionLoginBtn.addEventListener('click', () => {
          if (window.RadiologyAuth && typeof window.RadiologyAuth.signInWithGoogle === 'function') {
            window.RadiologyAuth.signInWithGoogle(window.location.href);
          } else {
            window.location.href = '../login/index.html';
          }
        });
      }
      if (commentInput) {
        if (!isGoogle) {
          commentInput.disabled = true;
          commentInput.placeholder = 'Sign in with Google to comment.';
        } else {
          commentInput.disabled = false;
          if (!activeReplyTarget) {
            commentInput.placeholder = 'Add to the discussion...';
          }
        }
      }
      if (commentPostPill && !isGoogle) {
        commentPostPill.disabled = true;
        commentPostPill.classList.remove('is-visible');
      }
    }

    if (commentCurrentAvatarEl) {
      commentCurrentAvatarEl.addEventListener('click', () => {
        const newSeed = 'user-' + Math.random().toString(36).substring(2, 10);
        const newAvatar = getDicebearAvatar(newSeed);
        if (!newAvatar) return;

        try {
          localStorage.setItem('my_radiology_user_avatar', newAvatar);
          const raw = localStorage.getItem('my_radiology_user_session');
          if (raw) {
            const session = JSON.parse(raw);
            session.avatar = newAvatar;
            session.isDicebear = true;
            localStorage.setItem('my_radiology_user_session', JSON.stringify(session));
          }
        } catch (e) {}

        commentCurrentAvatarEl.classList.remove('is-spinning');
        void commentCurrentAvatarEl.offsetWidth;
        commentCurrentAvatarEl.innerHTML = `<img class="comment-current-avatar-img" src="${newAvatar}" alt="You" />`;
        commentCurrentAvatarEl.classList.add('is-spinning');
      });
    }

    if (commentInput) {
      const handleInputChange = () => {
        adjustTextareaHeight();
        updatePostPillVisibility();
      };

      commentInput.addEventListener('input', handleInputChange);
      commentInput.addEventListener('keyup', handleInputChange);
      commentInput.addEventListener('change', handleInputChange);
      commentInput.addEventListener('paste', () => {
        setTimeout(handleInputChange, 10);
      });

      commentInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          if (commentInput.value.trim().length > 0) {
            commentForm.dispatchEvent(new Event('submit', { cancelable: true }));
          }
        }
      });

      updatePostPillVisibility();
    }

    // Initialize current user avatar UI
    updateCurrentAvatarUI();

    const STORAGE_COMMENTS_KEY = 'mrg_post_comments_v8';

    // Cleaned @ icon SVG
    const AT_RATE_SVG = `<svg class="comment-at-icon" viewBox="0 0 24 24" fill="currentColor" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path fill-rule="evenodd" clip-rule="evenodd" d="M16.5485 20.9074C16.7993 21.3985 16.6058 22.0046 16.0939 22.2098C13.9858 23.0552 11.6589 23.2302 9.43437 22.6966C6.885 22.0852 4.63785 20.5833 3.09784 18.4616C1.55783 16.3399 0.82623 13.7379 1.03488 11.1246C1.24352 8.51121 2.37869 6.0583 4.23584 4.20784C6.09298 2.35738 8.54997 1.23105 11.1641 1.03182C13.7782 0.832594 16.3775 1.57356 18.4936 3.12121C20.6097 4.66885 22.1035 6.9214 22.7058 9.47296C22.9026 10.3069 23 11.1549 23 12L23 12.0022C22.9999 12.5715 22.9555 13.1396 22.8676 13.7012C22.5877 15.7731 21.7158 19 19 19C16.6669 19 15.889 17.6669 15.6297 16.778C14.6219 17.5448 13.3641 18 12 18C8.68629 18 6 15.3137 6 12C6 8.68629 8.68629 6 12 6C15.3137 6 18 8.68629 18 12C18 12 18 14 17.9985 16C18 17 18.5 17 18.5 17C19.427 17 20.0112 16.2367 20.3791 15.3067C20.3882 15.2749 20.3987 15.2434 20.4106 15.2122C20.4524 15.1026 20.4921 14.9924 20.5296 14.8815C20.9613 13.5182 21 12 21 12H21.0031C21.0031 11.3083 20.9234 10.6143 20.7623 9.93171C20.2694 7.84334 19.0467 5.99971 17.3148 4.73301C15.5828 3.46632 13.4554 2.85986 11.3158 3.02292C9.17626 3.18599 7.1653 4.10785 5.64529 5.62239C4.12529 7.13693 3.19619 9.14455 3.02542 11.2835C2.85465 13.4224 3.45343 15.5521 4.71388 17.2886C5.97433 19.0251 7.81354 20.2544 9.90012 20.7548C11.6616 21.1773 13.5015 21.057 15.1819 20.4221C15.6977 20.2273 16.2977 20.4164 16.5485 20.9074ZM7.99803 12C7.99803 14.2102 9.78977 16.002 12 16.002C14.2102 16.002 16.002 14.2102 16.002 12C16.002 9.78978 14.2102 7.99803 12 7.99803C9.78977 7.99803 7.99803 9.78978 7.99803 12Z"/></svg>`;

    // Delete comment SVG (from user specification)
    const DELETE_COMMENT_SVG = `<svg class="comment-delete-svg" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
<g clip-path="url(#clip0_del)">
<path d="M21 5.98047C17.67 5.65047 14.32 5.48047 10.98 5.48047C9 5.48047 7.02 5.58047 5.04 5.78047L3 5.98047" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" />
<path d="M8.5 4.97L8.72 3.66C8.88 2.71 9 2 10.69 2H13.31C15 2 15.13 2.75 15.28 3.67L15.5 4.97" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" />
<path d="M18.85 9.14062L18.2 19.2106C18.09 20.7806 18 22.0006 15.21 22.0006H8.79002C6.00002 22.0006 5.91002 20.7806 5.80002 19.2106L5.15002 9.14062" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" />
<path d="M10.33 16.5H13.66" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" />
<path d="M9.5 12.5H14.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" />
</g>
<defs>
<clipPath id="clip0_del">
<rect width="24" height="24" fill="white"/>
</clipPath>
</defs>
</svg>`;

    // Seed realistic clinical comments with exact requested 1h ago, 3h ago, and clean replies without links
    // Seed realistic clinical comments showcasing breaks, links, bold, italic, and strikethrough
    const DEFAULT_COMMENTS = [
      {
        id: 'c-1',
        author: 'Dr. Aris Thorne',
